window.WORLD_WARS={"version":"0.17.0","wars":[{"id":"ww1","name":"第一次世界大战","years":"1914—1918","subtitle":"从七月危机，到战壕与帝国的终局","coverage":"1914年7月—1918年11月，53个月连续；另列刺杀前史与1919年和会。","intro":"一场巴尔干危机为什么成为世界战争？联盟、动员、帝国竞争与决策失误互相推动；速胜失效后，战壕、封锁、工业与社会动员把战争拖入长期消耗。","start":"1914-07","end":"1918-11","default":"1914-07","phases":[["1914-06","危机与开战"],["1915-01","扩大与僵持"],["1916-01","消耗战之年"],["1917-01","革命与新力量"],["1918-01","攻势、崩溃与停战"],["1919-01","和平的难题"]],"months":[{"id":"ww1-1914-06","date":"1914-06","title":"萨拉热窝：刺杀并没有自动写下战争结局","theaters":["巴尔干","外交"],"countries":["ah","rs","de"],"people":["斐迪南","普林西普"],"story":["6月28日，奥匈皇储斐迪南与妻子在萨拉热窝遇刺。刺杀发生在民族主义、帝国边疆和塞尔维亚问题交织的地区，却并不意味着各国当日已经决定打一场世界大战。","维也纳随后追究塞尔维亚责任，柏林的支持、俄国的保护姿态和各国对盟约信誉的判断，逐步放大危机。理解开战，应追踪接下来一个月的最后通牒与动员，而不是把全部责任归给一声枪响。"],"perspectives":[{"country":"ah","text":"奥匈统治者把塞尔维亚视为帝国边疆稳定的威胁。"},{"country":"rs","text":"塞尔维亚面临邻近大国的压力，刺客行为与政府责任不能直接画等号。"}],"sources":[{"id":"nam14","locator":"1914-06对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1914-07","date":"1914-07","title":"最后通牒与动员：局部危机越过门槛","theaters":["外交","巴尔干"],"countries":["ah","rs","de","ru","fr","uk"],"people":["威廉二世","尼古拉二世"],"story":["7月23日，奥匈向塞尔维亚提出最后通牒。塞方接受大部分要求，却未能消除奥匈发动战争的决心。28日奥匈宣战，俄国随后扩大动员，危机从巴尔干向欧洲联盟体系传导。","动员不仅是外交信号，也牵动铁路、兵员和作战时刻表。各国领导人担心迟动一步便失去优势，反而压缩了继续协商的空间。战争由一连串仍可辨认的政治选择扩展，绝非某个机械装置自行启动。"],"perspectives":[{"country":"de","text":"柏林支持奥匈，同时担心俄法夹击，军事部署愈加影响外交。"},{"country":"ru","text":"俄国维护巴尔干影响及塞尔维亚关系，却使德国把动员视为迫近的军事危险。"}],"sources":[{"id":"nam14","locator":"1914-07对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1914-08","date":"1914-08","title":"欧洲开战：比利时、坦能堡与青岛被卷入","theaters":["西线","东线","亚洲"],"countries":["de","fr","uk","ru","jp","cn"],"people":["霞飞","兴登堡","鲁登道夫"],"story":["德国先后对俄、法宣战，并入侵比利时，企图经北方迅速击败法国。英国以比利时中立及欧洲安全为重要理由参战，法国边境攻势受挫，英法军向南撤退，速胜计划开始接受现实检验。","东线俄军进入东普鲁士，在坦能堡遭德军重创；日本又对德国宣战，准备进攻其在中国山东的据点。欧洲战争迅速牵动亚洲与殖民地，中立的中国也无法置身于列强争夺之外。"],"perspectives":[{"country":"fr","text":"法国必须在边境失利后保持军队完整，保卫本土成为紧迫任务。"},{"country":"cn","text":"山东成为交战方争夺的空间，中国中立未能保障当地免受战争影响。"}],"sources":[{"id":"nam14","locator":"1914-08对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1914-09","date":"1914-09","title":"马恩河：没有攻下巴黎的军队","theaters":["西线","东线"],"countries":["fr","uk","de","ru","ah"],"people":["霞飞","小毛奇"],"story":["9月，德军逼近巴黎，却在连续行军中拉长补给与部队间距。英法军抓住德军部署间隙反击，第一次马恩河战役迫使德军后撤，迅速结束西线战争的设想落空。","德军在埃纳河一线据守，双方开始向北寻找能够迂回对手的空间。东线俄军则在加利西亚打击奥匈军。欧洲并未出现一个统一的胜负节奏：德国东线的胜利，无法替代奥匈承受的压力。"],"perspectives":[{"country":"de","text":"必须调整西线部署，在两线之间分配兵力。"},{"country":"fr","text":"守住巴黎方向并不等于收复失地，接下来仍需突破新形成的防线。"}],"sources":[{"id":"nam14","locator":"1914-09对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1914-10","date":"1914-10","title":"奔向海岸，走进战壕","theaters":["西线","中东"],"countries":["de","uk","fr","ot","ru"],"people":["恩维尔帕夏"],"story":["双方试图从对方北翼绕过去，战线却不断向英吉利海峡延伸。伊普尔附近激战，使沿海通道成为争夺重点；越来越多部队掘壕自保，机枪与炮兵让开阔地上的进攻极为昂贵。","月底，奥斯曼舰队袭击俄国黑海港口，帝国进一步卷入战争。西线尚未分出胜负，新的高加索与中东战场已经打开，海峡、帝国交通和宗教政治也被纳入战争。"],"perspectives":[{"country":"uk","text":"保住海峡港口关系到远征军运输和本土安全。"},{"country":"ot","text":"加入冲突后必须同时考虑俄国边境与英国控制的交通要道。"}],"sources":[{"id":"nam14","locator":"1914-10对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1914-11","date":"1914-11","title":"青岛陷落，巴士拉被占：战争越出欧洲","theaters":["亚洲","中东","西线"],"countries":["jp","cn","de","uk","ot"],"people":["加藤定吉"],"story":["11月，青岛德军在日英进攻下投降，日本扩大对山东的控制。欧洲之外的据点争夺，改变了中国的外交处境，也为战后山东问题埋下争议。","英印军在美索不达米亚登陆并占领巴士拉，英国与奥斯曼公开交战。西线第一次伊普尔战斗渐告结束，绵延战壕取代了夏季的机动作战；帝国士兵被运往远离故乡的前线，战争的全球性质更加清楚。"],"perspectives":[{"country":"jp","text":"借对德作战扩大东亚影响，目标并不限于欧洲盟友的需要。"},{"country":"uk","text":"动用印度等地兵力保护海路与波斯湾利益，殖民体系成为战争资源。"}],"sources":[{"id":"nam14","locator":"1914-11对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1914-12","date":"1914-12","title":"圣诞停火与仍在运转的战争","theaters":["西线","海战"],"countries":["uk","de","fr"],"people":["约翰·弗伦奇"],"story":["12月，西线部分地段出现非正式圣诞停火，士兵短暂停止射击，有的交换物品或掩埋遗体。它只发生于局部，不能被说成整条战线共同休战，更没有使各国政府停止战争。","同月，英军在福克兰群岛附近海战获胜，德国军舰又炮击英国沿海城镇。前线短暂相认与后方继续动员并存：普通人的接触可以打断敌意，却还不足以拆除正在扩大的人力与物资消耗体系。"],"perspectives":[{"country":"uk","text":"海军争夺交通线，沿海居民同时发现本土也可能直接遭袭。"},{"country":"de","text":"大陆战线僵持后，海上行动试图增加英国承受的压力。"}],"sources":[{"id":"nam14","locator":"1914-12对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1915-01","date":"1915-01","title":"飞艇飞向英国，战场伸向天空","theaters":["空战","海战"],"countries":["uk","de"],"people":["齐柏林"],"story":["1月，德国飞艇轰炸英国城镇，战争的危险越过海峡，进入平民生活。防空、警报和心理承受逐渐成为后方事务，天空不再只是侦察的辅助空间。","24日多格尔沙洲海战中，英国舰队与德国舰队交锋。海军争夺没有带来决定性的战略终局，双方仍须在保存主力、寻找出击机会和维持海上贸易之间权衡。"],"perspectives":[{"country":"de","text":"空袭与海上行动旨在把压力带到英国本土。"},{"country":"uk","text":"海军优势仍需维持，平民防护也成为战争治理的新问题。"}],"sources":[{"id":"nam15","locator":"1915-01对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1915-02","date":"1915-02","title":"潜艇与海峡：寻找战壕之外的突破口","theaters":["海战","中东","东线"],"countries":["de","uk","ot","ru"],"people":["丘吉尔"],"story":["德国扩大潜艇对商船的威胁，试图打击英国的补给与贸易。海上封锁和反封锁不只影响军舰，商船乘员、旅客与中立国也逐渐陷入风险。","英法舰队开始炮击达达尼尔海峡要塞，谋求打开通往俄国的海路。东线德军又在马祖里湖区重创俄军。各国都在寻找能够改变全局的侧翼，却必须面对新的地形、补给和外交代价。"],"perspectives":[{"country":"uk","text":"海峡行动希望以海军力量绕开西线僵局。"},{"country":"ru","text":"需要盟友支持和外部物资，东线损失进一步加大压力。"}],"sources":[{"id":"nam15","locator":"1915-02对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1915-03","date":"1915-03","title":"新沙佩勒与达达尼尔：突破为何没能延续","theaters":["西线","中东"],"countries":["uk","fr","de","ot"],"people":["丘吉尔","伊恩·汉密尔顿"],"story":["英印军在新沙佩勒一度攻入德国阵地，但通信、增援与火力衔接未能支持继续推进。打开第一道防线之后，如何及时把兵力和补给送进去，成为比最初突击更难的问题。","18日，英法舰队强行通过达达尼尔海峡的行动受挫，水雷与岸防使军舰遭受损失。海军未能独自完成任务，协约国转而准备登陆，最初希望缩短战争的行动开始走向漫长陆战。"],"perspectives":[{"country":"ot","text":"守住海峡可保护首都方向与重要交通。"},{"country":"uk","text":"必须在终止行动与扩大投入之间作出选择，沉没成本不能证明继续进攻必然正确。"}],"sources":[{"id":"nam15","locator":"1915-03对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1915-04","date":"1915-04","title":"毒气与登陆：战争跨过新的界限","theaters":["西线","中东"],"countries":["de","fr","uk","ot"],"people":["穆斯塔法·凯末尔","伊恩·汉密尔顿"],"story":["22日，德军在第二次伊普尔战役中大规模施放氯气，守军遭受突然打击，防毒装备与救护随之成为紧急需要。新武器带来恐怖，却没有自动解决突破和占领的问题。","25日，协约国在加里波利登陆。凯末尔等组织的奥斯曼防御阻止登陆军迅速向纵深推进，滩头阵地逐渐变为消耗战。与此同时，奥斯曼当局对亚美尼亚人的迫害与驱逐升级，战争中的国家暴力不能被战役叙事遮蔽。"],"perspectives":[{"country":"ot","text":"军队防御海峡；政府针对亚美尼亚人的暴力则是另一条必须辨认的历史进程。"},{"country":"uk","text":"多国及帝国部队登陆后，需要面对补给、疾病与山地防御的持续压力。"}],"sources":[{"id":"nam15","locator":"1915-04对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"armenian","locator":"1915-04对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":["gallipoli"]},{"id":"ww1-1915-05","date":"1915-05","title":"卢西塔尼亚与意大利参战","theaters":["海战","意大利","东线"],"countries":["de","uk","us","it","ah","ru"],"people":["威尔逊"],"story":["7日，德国潜艇击沉客轮卢西塔尼亚号，大量平民遇难，其中包括美国人。德国试图用潜艇削弱英国，却因此增加与美国决裂的风险，军事手段与外交后果紧密相连。","东线戈尔利采—塔尔努夫突破迫使俄军后撤；意大利则在伦敦条约承诺的领土利益推动下，于23日向奥匈宣战。战争规模再次扩大，新的参战国并没有迅速打破总体僵局。"],"perspectives":[{"country":"us","text":"政府仍维持中立，但本国公民遇难使对德关系进一步恶化。"},{"country":"it","text":"从中立转为协约国一方，期待领土收益，却将承受长期山地作战。"}],"sources":[{"id":"nam15","locator":"1915-05对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"usentry","locator":"1915-05对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1915-06","date":"1915-06","title":"伊松佐河：新的战线，熟悉的消耗","theaters":["意大利","中东"],"countries":["it","ah","uk","ot"],"people":["卡多尔纳"],"story":["意大利军队在伊松佐河一线发动攻势，山地、河流和既设防御使进攻困难。参战时希望通过新战线牵动奥匈，实际却走向一场又一场代价高昂的重复攻击。","加里波利的进攻也没有突破半岛。战线并非完全静止，局部阵地反复易手，但大量伤亡没有带来预想中的政治终局。观察这一月，要把战场推进的有限距离与持续消耗放在一起。"],"perspectives":[{"country":"it","text":"必须把参战承诺变成军事成果，地形却限制进攻。"},{"country":"ah","text":"在俄国与意大利两个方向分配兵力，防守成功仍意味着不断消耗。"}],"sources":[{"id":"nam15","locator":"1915-06对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1915-07","date":"1915-07","title":"殖民地投降，欧洲僵局仍在","theaters":["非洲","西线"],"countries":["de","uk"],"people":["博塔"],"story":["德属西南非洲守军于7月投降，南非军队的进攻改变了当地殖民控制。对欧洲政府而言这是战果，对当地居民而言则是统治关系继续重组，不能仅把殖民地写成地图上被换色的区域。","西线仍围绕战壕与有限据点作战，德国在胡赫使用火焰喷射器等手段。新技术接连投入，却没有立即恢复开战时期待的快速机动；军队与工业之间的联系日益紧密。"],"perspectives":[{"country":"de","text":"海外据点逐步孤立，主战场仍在欧洲。"},{"country":"uk","text":"帝国体系提供兵员与区域力量，殖民战争的后果延续到停战之后。"}],"sources":[{"id":"nam15","locator":"1915-07对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1915-08","date":"1915-08","title":"华沙失守，加里波利再押一注","theaters":["东线","中东"],"countries":["ru","de","ah","uk","ot"],"people":["尼古拉二世","穆斯塔法·凯末尔"],"story":["德军占领华沙，俄军在大撤退中放弃大片地区，运输、军需与难民问题彼此挤压。避免部队被围成为现实选择，领土损失则不断削弱政府威信。","协约国在苏夫拉等处增兵登陆，试图打破加里波利僵局，但新的攻势仍受阻。一个战场上的困难促使人们期待另一个方向的突破，却也可能把有限资源分散到更多无法迅速取胜的前线。"],"perspectives":[{"country":"ru","text":"军事撤退与后方不满相互强化，战争负担进入政治核心。"},{"country":"ot","text":"守住半岛的代价持续累积，防御胜利并不意味着帝国其他方向安全。"}],"sources":[{"id":"nam15","locator":"1915-08对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1915-09","date":"1915-09","title":"卢斯攻势与俄皇亲掌统帅权","theaters":["西线","东线"],"countries":["uk","fr","de","ru"],"people":["尼古拉二世","约翰·弗伦奇"],"story":["英军在卢斯、法军在香槟等地进攻，试图用协同压力打开西线。卢斯初期推进未能持续，增援和通信问题使局部机会流失，战场再度陷入相持。","尼古拉二世亲自担任俄军最高统帅，把皇室声望与战争成败绑得更紧。德国也调整潜艇政策，以缓解美国压力；作战选择、国内统治与中立国反应，已成为同一场战争的不同侧面。"],"perspectives":[{"country":"ru","text":"皇帝承担更直接的军事责任，却无法单靠更换统帅解决后勤与社会危机。"},{"country":"uk","text":"扩大军队之后，如何训练、指挥与协同仍需学习。"}],"sources":[{"id":"nam15","locator":"1915-09对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1915-10","date":"1915-10","title":"塞尔维亚遭夹击，巴尔干通道被改写","theaters":["巴尔干"],"countries":["rs","ah","de","uk","fr"],"people":["麦肯森"],"story":["德国、奥匈与新加入同盟国的保加利亚进攻塞尔维亚。塞军面临多方向压力，协约国在萨洛尼卡登陆，仍未能及时改变塞尔维亚本土的困境。","这一变化使同盟国与奥斯曼之间的陆上联系更加有利，巴尔干不再只是1914年开战的起点，而成为补给、联盟与帝国交通的持续争夺地。小国的生存与大国的战略安排之间，始终存在不对称。"],"perspectives":[{"country":"rs","text":"保全部队与国家存续成为紧迫问题。"},{"country":"de","text":"通过巴尔干改善与奥斯曼的联系，战略收益不限于占领塞尔维亚。"}],"sources":[{"id":"nam15","locator":"1915-10对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1915-11","date":"1915-11","title":"塞军撤退与两河远征的极限","theaters":["巴尔干","中东"],"countries":["rs","uk","ot"],"people":["汤森德"],"story":["塞尔维亚军队与部分平民在严酷条件下向亚得里亚海方向撤退，军事失败转为饥饿、疾病和流亡。保存下来的部队后来仍会回到战争，并非国家在地图上被占领便不再抵抗。","美索不达米亚方向，英印军在泰西封附近与奥斯曼军交战后退回库特。向巴格达推进的野心超出当地补给承受力，一次远征的边界开始显露。"],"perspectives":[{"country":"rs","text":"撤退也是继续抵抗的艰难选择，代价主要由军民承担。"},{"country":"uk","text":"帝国部队能推进多远，取决于河运、医疗和补给，而非地图上的箭头。"}],"sources":[{"id":"nam15","locator":"1915-11对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1915-12","date":"1915-12","title":"从加里波利撤离，在库特陷入围困","theaters":["中东","西线"],"countries":["uk","fr","ot"],"people":["伊恩·汉密尔顿","黑格"],"story":["协约国开始撤出加里波利的安扎克与苏夫拉阵地。数月消耗没有打开海峡，撤离意味着承认原计划失败；直到次年1月，半岛撤退才全部完成。","库特的英印军却在此时遭到围困，救援成为另一项艰难任务。西线黑格接替弗伦奇指挥英国远征军，来年的大规模进攻开始酝酿，指挥更替并没有使战争的结构性困局消失。"],"perspectives":[{"country":"ot","text":"成功抵御半岛进攻，同时继续在两河战场争夺主动。"},{"country":"uk","text":"结束一处远征时又需解救另一处被围部队，资源分配愈加困难。"}],"sources":[{"id":"nam15","locator":"1915-12对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1916-01","date":"1916-01","title":"撤离完成，征兵进入英国政治","theaters":["中东","后方"],"countries":["uk","ot"],"people":["阿斯奎斯"],"story":["加里波利最后一批协约国军撤走，奥斯曼守住海峡。英国原本希望通过侧翼远征改变战争，最终不得不把经历失败的部队和资源重新安排到其他方向。","英国通过军事服役法，逐步转向强制征兵。志愿报名已不足以持续支持大规模战争，国家与个人的关系随之改变；战斗力来自前线，也来自家庭、工厂和政府动员的承受限度。"],"perspectives":[{"country":"uk","text":"人员补充由个人志愿进一步转向国家强制。"},{"country":"ot","text":"海峡胜利提高信心，却没有解除高加索和两河压力。"}],"sources":[{"id":"nam16","locator":"1916-01对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1916-02","date":"1916-02","title":"凡尔登：一座要塞城市为何成为消耗中心","theaters":["西线","东线"],"countries":["fr","de","ru","ot"],"people":["法尔肯海因","贝当"],"story":["21日，德军进攻凡尔登，猛烈炮火之后向法国阵地推进，杜奥蒙堡很快失守。法国组织增援与轮换，贝当参与稳住防御，补给道路成为维持战斗的生命线。","凡尔登的象征意义使撤退更难被接受，战斗由争夺要塞扩大为持续消耗。德方作战意图的具体解释仍有讨论，但两军实际陷入的兵员与炮弹消耗十分明确。同期俄军夺取埃尔祖鲁姆，奥斯曼高加索防线承压。"],"perspectives":[{"country":"fr","text":"保卫本土与军队士气叠加，补给和轮换关系到能否坚持。"},{"country":"de","text":"未能以一次猛攻结束战斗，必须不断追加资源维持压力。"}],"sources":[{"id":"nam16","locator":"1916-02对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"verdun","locator":"1916-02对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1916-03","date":"1916-03","title":"凡尔登两岸与库特救援","theaters":["西线","中东"],"countries":["fr","de","uk","ot"],"people":["贝当","汤森德"],"story":["凡尔登战斗向默兹河两岸扩大，山丘与村庄成为反复争夺的位置。防守不只是留在原地，部队还要轮换、修复阵地、运入弹药并把伤员送出。","美索不达米亚方向，英军又一次救援库特失败。战壕中的炮火和远征军的饥饿看似相距遥远，却共同显示工业战争的底层问题：战斗单位能否持续得到人、粮食、运输和医疗支持。"],"perspectives":[{"country":"fr","text":"防御强度取决于后方运输与军队组织。"},{"country":"uk","text":"解围攻势未能接通补给，被围部队的时间越来越少。"}],"sources":[{"id":"nam16","locator":"1916-03对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1916-04","date":"1916-04","title":"库特投降，爱尔兰起义：后方也在裂变","theaters":["中东","后方"],"countries":["uk","ot"],"people":["汤森德"],"story":["29日，库特被围英印军投降，英国的两河远征遭到严重挫折。投降之后的押送与战俘处境也属于战争历史，军队从战场消失并不意味着人员苦难随之结束。","爱尔兰发生复活节起义，英国镇压及随后处决引起深远反响。对政府而言是战时安全问题，对民族主义者而言则是独立诉求；帝国在海外动员兵员时，本身的统治关系也受到挑战。"],"perspectives":[{"country":"uk","text":"必须同时处理海外战败和帝国内部反抗。"},{"country":"ot","text":"库特获胜暂时稳住两河局面，但英国此后仍会重新组织进攻。"}],"sources":[{"id":"nam16","locator":"1916-04对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1916-05","date":"1916-05","title":"日德兰：舰队交战，没有改写封锁","theaters":["海战","意大利"],"countries":["uk","de","it","ah"],"people":["杰利科","舍尔"],"story":["31日，英国大舰队与德国公海舰队在日德兰附近展开主力交锋。侦察、信号和舰队机动决定着交战机会，双方均有舰艇沉没，胜负不能仅用某一类损失数字判断。","战斗延续到6月，德国舰队返回基地，英国总体海上控制与封锁仍然存在。意大利战线又遭奥匈特伦蒂诺攻势，协约国需要通过不同战场的行动互相减压。"],"perspectives":[{"country":"de","text":"战术战果未能打破英国对北海交通的总体控制。"},{"country":"uk","text":"保存并运用海军优势，比单次交锋的胜负宣称更影响长期战争。"}],"sources":[{"id":"nam16","locator":"1916-05对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1916-06","date":"1916-06","title":"布鲁西洛夫攻势与阿拉伯起义","theaters":["东线","中东"],"countries":["ru","ah","de","ot","uk"],"people":["布鲁西洛夫","侯赛因"],"story":["4日，俄军布鲁西洛夫攻势在广阔正面展开，对奥匈阵地造成重大打击。准备与攻击方式改进带来突破，但继续利用成果仍依赖预备队、交通和其他方向的配合。","阿拉伯起义在汉志展开，侯赛因方面反抗奥斯曼统治，并与英国发生合作。战时独立承诺、帝国利益和地方政治从此纠缠，不能把阿拉伯社会的不同选择简化为单一阵营。"],"perspectives":[{"country":"ru","text":"军事成功短期提振局势，却无法消除国家长期积累的危机。"},{"country":"ot","text":"欧洲与中东压力叠加，帝国既面对外敌，也面对统治内部的反抗。"}],"sources":[{"id":"nam16","locator":"1916-06对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1916-07","date":"1916-07","title":"索姆河：炮击之后，突破没有如期到来","theaters":["西线"],"countries":["uk","fr","de"],"people":["黑格","罗林森"],"story":["1日，英法联军在索姆河发动进攻，意在突破德军阵地并缓解凡尔登压力。长时间炮击未能彻底摧毁深层防御，许多进攻部队走入仍可射击的机枪和炮火范围。","英国军队首日损失极其严重，法军在部分地段取得进展，但整个战线没有出现预想中的快速崩溃。进攻继续，目标逐渐转为争夺村庄、高地和磨损对手，战场行动与原先许诺的结果之间出现巨大距离。","索姆河将新组建军队、工业火力与指挥协同的问题集中暴露。理解它，不只应记住首日灾难，也要追踪为何明知代价高昂仍继续投入，以及后续战术究竟怎样调整。"],"perspectives":[{"country":"uk","text":"志愿军的大规模投入使损失直接进入众多家庭和地方社会。"},{"country":"de","text":"坚固防御承受持续压力，也需不断补充守军，消耗并非只有进攻方承担。"}],"sources":[{"id":"nam16","locator":"1916-07对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"somme","locator":"1916-07对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1916-08","date":"1916-08","title":"罗马尼亚入战与德国最高统帅更替","theaters":["东线","中东"],"countries":["ru","ah","de","uk","ot"],"people":["兴登堡","鲁登道夫"],"story":["罗马尼亚加入协约国，希望在战争中争取国家目标，却很快面对同盟国反击。新参战国打开一条战线，也需要盟友提供并不总能及时到达的支持。","兴登堡出任德国总参谋长，鲁登道夫权力上升；德国进一步强化战争动员。中东罗马尼战役中，奥斯曼进攻被击退，西奈方向的主动权逐步变化，多条战线同时索取有限资源。"],"perspectives":[{"country":"de","text":"军事领导层更替推动动员强化，战争与国内经济结合更深。"},{"country":"ru","text":"援助盟友又增加东线负担，局部胜利难以保证联盟整体稳定。"}],"sources":[{"id":"nam16","locator":"1916-08对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1916-09","date":"1916-09","title":"坦克首次参战，技术尚不能独立取胜","theaters":["西线"],"countries":["uk","fr","de"],"people":["黑格"],"story":["15日，英军在索姆河的弗莱尔—库尔瑟莱特作战中首次把坦克投入战场。一些车辆帮助步兵突破，另一些却因故障、地形和行动困难未能发挥预期作用。","坦克带来新可能，但数量、可靠性和步炮协同还不足以结束僵局。把它写成突然改变一切的奇迹，会遮蔽驾驶、维修、补给以及配合战术的长期磨合。"],"perspectives":[{"country":"uk","text":"试验新武器的同时，必须承受技术尚未成熟的局限。"},{"country":"de","text":"防御者面对新威胁，也在寻找火炮、障碍和战术应对。"}],"sources":[{"id":"nam16","locator":"1916-09对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"somme","locator":"1916-09对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1916-10","date":"1916-10","title":"杜奥蒙堡收复，胜利被拆成小块","theaters":["西线"],"countries":["fr","de","uk"],"people":["尼韦尔","贝当"],"story":["法军反攻收复杜奥蒙堡，凡尔登方向的力量变化开始显现。曾经象征巨大危机的要塞重新易手，但收复据点并没有抹去此前数月的人命损失。","索姆河仍在艰苦推进，有限地段的得失成了作战成果的主要单位。战争评价也因而困难：战术进展、对敌消耗、己方损失和社会承受力，未必指向同一个答案。"],"perspectives":[{"country":"fr","text":"收复阵地改善战场与士气，却需要面对军队疲惫。"},{"country":"de","text":"在凡尔登与索姆河持续承压，防守同样消耗大量资源。"}],"sources":[{"id":"nam16","locator":"1916-10对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1916-11","date":"1916-11","title":"索姆河落幕，帝国开始寻找出口","theaters":["西线","后方"],"countries":["uk","fr","de","ah"],"people":["弗朗茨·约瑟夫一世","卡尔一世"],"story":["索姆河攻势在11月结束，没有实现决定性突破。战线移动有限，军队却被重新塑造：炮兵、步兵、侦察和后勤的协同经验，在巨大损失中逐步积累。","奥匈皇帝弗朗茨·约瑟夫去世，卡尔一世继位。长期战争加重粮食和民族关系压力，新君面对的是一个必须依赖盟友、又越来越难承受战争的帝国。"],"perspectives":[{"country":"uk","text":"需要解释投入与成果之间的落差，并准备下一年的行动。"},{"country":"ah","text":"王位更替无法自动修复社会、经济和多民族统治的裂缝。"}],"sources":[{"id":"nam16","locator":"1916-11对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"somme","locator":"1916-11对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1916-12","date":"1916-12","title":"凡尔登结束，饥饿延续","theaters":["西线","后方"],"countries":["fr","de","uk"],"people":["劳合·乔治","尼韦尔"],"story":["凡尔登的大规模战斗阶段告终，法军收复部分失地。两军在这一年投入的人力与火力，已使战争远离最初设想的短期决战。","劳合·乔治成为英国首相，法国也调整军事指挥。德国平民进入食品匮乏的严冬，封锁、农业困难和分配问题叠加；战争的承受力，越来越取决于战壕之外的人是否还能继续生活。"],"perspectives":[{"country":"de","text":"后方粮食危机削弱社会承受力，不能被前线宣传取代。"},{"country":"uk","text":"领导层希望改善战争统筹，仍需协调陆军、海军、工业与盟友。"}],"sources":[{"id":"nam16","locator":"1916-12对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1917-01","date":"1917-01","title":"一封电报与潜艇战争的赌注","theaters":["外交","海战"],"countries":["de","us","uk"],"people":["齐默尔曼","威尔逊"],"story":["德国决定恢复无限制潜艇战，希望在美国形成有效军事力量之前切断英国海运。它把争取时间与冒险扩大敌人绑在一起，海上战略成为一场政治赌博。","齐默尔曼电报向墨西哥提出在美德开战时合作的设想，被英国截获并在随后公开。美国舆论对德国意图的认识进一步改变，但从愤怒到宣战仍要经过国内政治程序。"],"perspectives":[{"country":"de","text":"寄望潜艇先迫使英国屈服，低估了长期增加敌手的风险。"},{"country":"us","text":"仍在中立与介入之间权衡，本土安全与海上权益逐渐连在一起。"}],"sources":[{"id":"nam17","locator":"1917-01对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"usentry","locator":"1917-01对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1917-02","date":"1917-02","title":"海运遭袭，旧外交关系断裂","theaters":["海战","外交"],"countries":["de","us","uk"],"people":["威尔逊"],"story":["德国从2月起实施无限制潜艇战，不再按原有限制对待许多航区内船舶，美国与德国断交。商船、粮食与燃料成为战争手段的直接目标，海运损失关系到英国能坚持多久。","此时美国尚未正式参战，英国也不能只等待援助。护航、反潜和运输组织逐渐成为回应，技术与制度的组合，比单纯计算潜艇数量更能说明后来的变化。"],"perspectives":[{"country":"uk","text":"海上生命线承压，必须保护贸易船队。"},{"country":"us","text":"断交并非宣战，但已显著缩小恢复正常关系的空间。"}],"sources":[{"id":"nam17","locator":"1917-02对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"usentry","locator":"1917-02对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1917-03","date":"1917-03","title":"俄国革命与德国后撤","theaters":["东线","西线","后方"],"countries":["ru","de","fr","uk"],"people":["尼古拉二世","克伦斯基"],"story":["俄国首都抗议、粮食困难与军队反应汇聚，尼古拉二世退位，临时政府成立。按俄国旧历称二月革命，按公历主要发生在3月；名称与日期口径必须区分。","西线德军主动退到兴登堡防线，缩短战线、加强防御，也在撤退中破坏设施并迁移居民。俄国革命没有立即结束其参战，西线后撤也不等于德国接受失败，各方仍在重新配置战争。"],"perspectives":[{"country":"ru","text":"新政府继承战争与社会诉求，继续作战的决定将面临考验。"},{"country":"de","text":"用有计划后撤改善防守条件，把空间换成兵力和工事优势。"}],"sources":[{"id":"nam17","locator":"1917-03对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1917-04","date":"1917-04","title":"美国参战，法国攻势受挫","theaters":["外交","西线"],"countries":["us","fr","uk","de","ru"],"people":["威尔逊","尼韦尔","列宁"],"story":["6日美国对德国宣战，潜艇袭击与外交冲突终于转化为正式战争。美国的工业、金融与兵员潜力重要，但部队训练、运输和投入前线仍需时间，不能把宣战日当作美军已经全面到场。","法国尼韦尔攻势未能实现许诺的突破，严重伤亡引发军队不满，之后出现哗变。列宁返回俄国，主张与临时政府不同的政治路线；联盟力量增加的同时，旧成员的内部稳定却在动摇。"],"perspectives":[{"country":"us","text":"必须把参战决议转换为军队、运输和动员体系。"},{"country":"fr","text":"军队拒绝无望进攻的情绪，需要通过指挥调整、休整和待遇改善应对。"}],"sources":[{"id":"nam17","locator":"1917-04对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"usentry","locator":"1917-04对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1917-05","date":"1917-05","title":"军心、护航与继续战争的条件","theaters":["西线","海战"],"countries":["fr","uk","us","de"],"people":["贝当"],"story":["贝当接掌法国军队指挥，面对的首要问题是恢复信任与作战秩序。他限制缺乏把握的大规模进攻，改善休假和补给，同时维持军纪，军队危机不能只靠一纸命令解决。","大西洋护航逐步扩大使用，把商船组织成有保护的船队。战争的关键不总是新的决战，也可能是让运输损失降下来、让部队愿意继续执行任务的制度改变。"],"perspectives":[{"country":"fr","text":"保存军队与恢复士气成为争取未来行动能力的前提。"},{"country":"uk","text":"保障粮食和物资抵达，比单次击沉敌艇更关系长期生存。"}],"sources":[{"id":"nam17","locator":"1917-05对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1917-06","date":"1917-06","title":"梅西讷：有限目标能否换来可靠成果","theaters":["西线"],"countries":["uk","de","us"],"people":["普卢默","潘兴"],"story":["英军在梅西讷通过长期准备的地道爆破、炮火与步兵协同夺取高地。行动目标相对有限，成果显示精心准备能够改善战术表现，却并未证明西线整体突破已经容易实现。","美军人员开始抵达法国，潘兴建立远征军体系。新力量需要训练、装备与组织，联盟也需决定美军如何与既有部队协同，未来的优势正在形成，尚未全部兑现。"],"perspectives":[{"country":"uk","text":"有限目标作战提供经验，随后是否扩大攻势仍是另一项判断。"},{"country":"us","text":"从抵达欧洲到形成独立作战能力，需要跨越漫长的后勤与训练过程。"}],"sources":[{"id":"nam17","locator":"1917-06对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1917-07","date":"1917-07","title":"俄军攻势失败，佛兰德再度开战","theaters":["东线","西线"],"countries":["ru","de","uk","fr"],"people":["克伦斯基","黑格"],"story":["俄国临时政府发动新的攻势，未能扭转战局，军队瓦解和社会不满进一步扩大。继续战争的政策与民众对和平、土地和生活的要求越来越难调和。","31日，第三次伊普尔战役开始。英军希望向比利时方向推进，炮火破坏排水后，降雨与地形逐步加重困难。准备突破的战场，正变成既消耗军队又阻碍运输的泥泞空间。"],"perspectives":[{"country":"ru","text":"军事失利削弱临时政府合法性。"},{"country":"uk","text":"战略目标必须通过极为不利的地形和补给条件才能实现。"}],"sources":[{"id":"nam17","locator":"1917-07对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1917-08","date":"1917-08","title":"中国参战，世界战争中的弱国处境","theaters":["外交","西线"],"countries":["cn","de","ah","uk","fr"],"people":["段祺瑞"],"story":["14日，中国对德国、奥匈宣战。参战既与国内政治有关，也包含争取战后国际地位、处理列强权益的期待。此前和此后赴欧的华工承担运输、修筑与清理等繁重劳动，是中国参与战争的重要部分。","佛兰德攻势仍在继续，华工与帝国劳工在战线后方维持战争机器。国家宣布加入胜方阵营，并不保证战后诉求会自动得到满足；中国的经历将延伸到巴黎和会及山东问题。"],"perspectives":[{"country":"cn","text":"参战被寄予改善国际地位的希望，实际谈判能力仍受强权关系限制。"},{"country":"uk","text":"前线依赖跨国劳工体系，战争贡献并不限于持枪作战。"}],"sources":[{"id":"nam17","locator":"1917-08对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"chinaWW1","locator":"1917-08对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1917-09","date":"1917-09","title":"有限推进与和平希望的破灭","theaters":["西线","东线"],"countries":["uk","de","ru"],"people":["普卢默","克伦斯基"],"story":["英军在第三次伊普尔的部分阶段采取有限目标推进，在梅宁路等处获得局部成果。战术调整可以减少某些困难，却无法让已经破坏的地形、持续伤亡和总目标之间的矛盾消失。","俄国经历科尔尼洛夫事件，临时政府与军队高层的冲突加深，布尔什维克影响上升。战争的结局正被军队内部、城市政治和后方供给共同改变，而不只取决于前线谁又占领一处阵地。"],"perspectives":[{"country":"uk","text":"局部进展仍需接受成果与代价的比较。"},{"country":"ru","text":"政治权威继续分裂，维持原有战争路线更加困难。"}],"sources":[{"id":"nam17","locator":"1917-09对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1917-10","date":"1917-10","title":"卡波雷托：一条战线突然崩开","theaters":["意大利","西线"],"countries":["it","ah","de","uk","fr"],"people":["卡多尔纳","迪亚兹"],"story":["24日，德奥军在卡波雷托发起进攻，意军防线遭到突破。部队快速后撤，民众流离失所，失败不只是战术问题，也暴露指挥、士气和组织体系的脆弱。","意大利随后退到皮亚韦河方向，协约国增援帮助稳定局面。佛兰德战斗仍在继续，加拿大等部队参与帕斯尚达尔攻坚；同一联盟内部，一处成功也无法补偿另一处突然出现的危机。"],"perspectives":[{"country":"it","text":"保住军队与重新组织防御比继续争取领土更迫切。"},{"country":"ah","text":"借德军协同取得突破，却未能一举迫使意大利退出战争。"}],"sources":[{"id":"nam17","locator":"1917-10对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1917-11","date":"1917-11","title":"革命、坦克与盟军新协调","theaters":["东线","西线","外交"],"countries":["ru","de","uk","fr","it"],"people":["列宁","克列孟梭","黑格"],"story":["布尔什维克在俄国夺取政权，主张退出战争；十月革命的名称采用旧历，主要行动按公历在11月。新政权开始推动和平交涉，东线力量配置即将变化。","英军在康布雷集中使用坦克，一度突破德国防御，德军反攻又收回大片阵地。法国克列孟梭执政，盟国建立最高战争委员会；技术创新和政治协调都重要，却都无法独立替代持续作战能力。"],"perspectives":[{"country":"ru","text":"和平承诺必须在德国压力、国内革命和国家生存之间兑现。"},{"country":"fr","text":"希望加强联盟统筹，准备应对俄国退出后的兵力变化。"}],"sources":[{"id":"nam17","locator":"1917-11对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1917-12","date":"1917-12","title":"东线停战，耶路撒冷易手","theaters":["东线","中东"],"countries":["ru","de","uk","ot"],"people":["列宁","艾伦比"],"story":["俄德签订停战安排，谈判进一步展开。德国开始看到从东线腾出力量的可能，俄国则希望结束军队与社会无法继续承受的战争。停战仍不等于已有可接受的最终和平条件。","英军进入耶路撒冷，巴勒斯坦战局改变。战争前景在两端同时变化：德国准备在西线争取机会，奥斯曼则在中东继续丧失主动，盟国的得失并不总能同步。"],"perspectives":[{"country":"de","text":"希望利用东线变化，在美国力量全面到达前改变西线。"},{"country":"ot","text":"领土与交通受压，帝国需要应对越来越不利的区域局势。"}],"sources":[{"id":"nam17","locator":"1917-12对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1918-01","date":"1918-01","title":"十四点原则与欧洲社会的疲惫","theaters":["外交","后方"],"countries":["us","de","ru","uk","fr"],"people":["威尔逊"],"story":["威尔逊提出十四点和平原则，试图以公开外交、国际组织和民族问题安排构建战后秩序。它为和平赋予新语言，却没有消除各盟国在领土、赔偿和帝国利益上的差异。","德国等地出现罢工与不满，俄德谈判也因苛刻条件陷入困境。前线仍在准备下一次攻势，后方却越来越追问战争还要持续多久，社会承受力成为战略的一部分。"],"perspectives":[{"country":"us","text":"以和平主张争取国际影响，并为美国参战解释目标。"},{"country":"de","text":"需要维持生产和兵员，后方不满使速胜愿望更加迫切。"}],"sources":[{"id":"nam18","locator":"1918-01对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"fourteen","locator":"1918-01对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1918-02","date":"1918-02","title":"谈判破裂后，德国再向东推进","theaters":["东线","外交"],"countries":["ru","de"],"people":["列宁","托洛茨基"],"story":["布列斯特谈判未能带来双方都可接受的条件，德国恢复进攻，俄国新政权面对更直接的军事危险。革命者关于战争与和平的分歧，此时必须接受军队战斗力和领土现实的检验。","列宁推动接受严苛和约，优先保住政权与喘息机会。退出大战并不意味着俄国社会获得稳定和平，国内战争和外部干预仍将延续，战场之间的边界并不整齐。"],"perspectives":[{"country":"ru","text":"在屈辱条件与继续无力作战之间作出艰难选择。"},{"country":"de","text":"利用军事优势扩大谈判要求，同时准备把主要机会押向西线。"}],"sources":[{"id":"nam18","locator":"1918-02对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1918-03","date":"1918-03","title":"布列斯特和约与德国春季攻势","theaters":["东线","西线"],"countries":["ru","de","uk","fr"],"people":["列宁","鲁登道夫","福煦"],"story":["3日，苏维埃俄国签署布列斯特—立托夫斯克和约，付出重大领土与政治代价退出对德战争。德国随后在21日发动西线春季攻势，试图在美军大量投入之前击败英法。","德军运用新的突击方式取得快速进展，英法面临严重危机。但突破之后，补给、预备队和明确战略目标仍然决定推进能否持续。盟国也在危机中加强统一指挥，福煦的统筹地位逐渐确立。"],"perspectives":[{"country":"de","text":"把时间压力转换为进攻压力，寄望最后的大规模机会。"},{"country":"uk","text":"必须保持与法军联系，避免撤退演变为联盟战线分裂。"}],"sources":[{"id":"nam18","locator":"1918-03对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1918-04","date":"1918-04","title":"德军继续进攻，却离终局仍远","theaters":["西线"],"countries":["de","uk","fr","us"],"people":["鲁登道夫","福煦"],"story":["德军在利斯河方向继续进攻，英军和盟军承受巨大压力。前线重新出现大幅移动，战争似乎回到1914年的机动状态，但补给道路和部队损耗并未随战线移动而改善。","德国夺取土地，却难以把多次局部突破合成决定性结果。美国兵力持续增加，盟军统一协调也在加强；一方通过进攻消耗最后的精锐，另一方则在等待新增力量成熟。"],"perspectives":[{"country":"de","text":"攻击次数增加，能够用于下一轮作战的精锐却不断减少。"},{"country":"us","text":"运输与训练正把潜在资源转为逐步可用的战场力量。"}],"sources":[{"id":"nam18","locator":"1918-04对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1918-05","date":"1918-05","title":"埃纳河突破，把危险带回巴黎方向","theaters":["西线"],"countries":["de","fr","uk","us"],"people":["鲁登道夫","潘兴"],"story":["德军在埃纳河方向突破，将战线再次推向马恩河与巴黎方向。突然成功制造巨大压力，却也使德国部队展开到更长的战线上，难以同时维持所有方向的主动。","美军开始承担更明显的战斗任务。盟军需要把新兵力与已有防御结合，而德国则必须在持续进攻与逐渐不足的补给之间选择，战场上的势头与长期力量对比正相互背离。"],"perspectives":[{"country":"fr","text":"保卫巴黎方向与维持军队衔接同时变得紧迫。"},{"country":"de","text":"占领更多土地并未解决击垮盟军的核心目标。"}],"sources":[{"id":"nam18","locator":"1918-05对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1918-06","date":"1918-06","title":"美军投入，意大利守住皮亚韦河","theaters":["西线","意大利"],"countries":["us","fr","de","it","ah"],"people":["潘兴","迪亚兹"],"story":["美军在贝洛森林等处参与激烈战斗，显示新的协约国力量已经进入前线。美军仍在学习现代战争，但数量、工业和运输支持使其作用不断扩大。","奥匈在皮亚韦河发动攻势受挫，意大利在卡波雷托后的防御整顿取得效果。德国与奥匈都需要决定性成果，却越来越难以承受失败后的再次投入，联盟内部的疲惫相互传递。"],"perspectives":[{"country":"us","text":"开始用实际作战承担联盟任务，经验和伤亡也随之增长。"},{"country":"ah","text":"进攻未果加剧军需与社会压力，帝国回旋空间继续缩小。"}],"sources":[{"id":"nam18","locator":"1918-06对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1918-07","date":"1918-07","title":"第二次马恩河：主动权开始换手","theaters":["西线"],"countries":["de","fr","us","uk"],"people":["福煦","鲁登道夫"],"story":["德国在马恩河一线再次进攻，盟军防御与反击挫败其意图。18日起的反攻把德军逐渐推回去，法国、美国等军队的协同作用开始更加明显。","这并不是某一瞬间所有德国部队同时败退，而是战略进攻能力逐渐耗尽的转折。德国难以补足损失，盟军却能组织连续行动，战争从寻找最后突破转向如何应对持续后退。"],"perspectives":[{"country":"de","text":"必须接受攻势未能赢得战争，并开始防守越来越不利的局面。"},{"country":"fr","text":"经过长期消耗后，获得组织反攻与收复失地的条件。"}],"sources":[{"id":"nam18","locator":"1918-07对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1918-08","date":"1918-08","title":"亚眠与百日攻势：连续压力取代单次豪赌","theaters":["西线"],"countries":["uk","fr","us","de"],"people":["福煦","黑格"],"story":["8日，盟军在亚眠发动攻击，结合突然性、坦克、炮兵和步兵协同取得进展。德军的俘虏与损失反映士气和组织承受力的下降，鲁登道夫将这一天视为严重打击。","此后的百日攻势并非一场连续不歇的冲锋，而是相互衔接的多次行动。盟军调整攻击方向，不断迫使德军放弃阵地；资源优势与战术学习开始转化为较持续的成果。"],"perspectives":[{"country":"uk","text":"部队经验与多兵种协同改善，但仍需支付伤亡代价。"},{"country":"de","text":"难以再通过局部坚守扭转总体资源与士气的劣势。"}],"sources":[{"id":"nam18","locator":"1918-08对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1918-09","date":"1918-09","title":"兴登堡防线承压，盟友开始退出","theaters":["西线","巴尔干","中东"],"countries":["de","uk","fr","us","ot"],"people":["福煦","艾伦比"],"story":["盟军攻击兴登堡防线，美军在圣米耶勒及默兹—阿尔贡方向作战，德军后退压力加大。防御工事并非不可突破，关键在于守军是否还能获得足够兵员、物资和信心。","巴尔干战线突破后保加利亚停战，中东米吉多作战重创奥斯曼军。德国最高统帅部要求寻求停战，前线困难终于以政治形式进入决策，盟友退出又进一步压缩德国的选择。"],"perspectives":[{"country":"de","text":"军事领导层开始要求政治当局寻找战争出口。"},{"country":"ot","text":"中东主力受挫，继续战争的基础迅速削弱。"}],"sources":[{"id":"nam18","locator":"1918-09对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1918-10","date":"1918-10","title":"帝国瓦解，停战接连到来","theaters":["外交","意大利","后方"],"countries":["de","ah","ot","us","it"],"people":["卡尔一世","威尔逊","迪亚兹"],"story":["奥斯曼签署穆德罗斯停战协定，奥匈在民族运动、军队疲惫和意大利攻势中迅速失去整体控制。战争不是只由德国一国的决定结束，同盟国体系正在逐步解体。","德国与威尔逊交涉停战条件，政府改革与军队危机并行。海军内部拒绝最后冒险行动的反抗很快扩大，军事服从的裂缝开始影响政体本身，停战与革命相互推动。"],"perspectives":[{"country":"ah","text":"多民族帝国的政治框架已难维持，各民族政治力量寻找独立出路。"},{"country":"de","text":"改革与停战交涉赶不上社会危机扩大的速度。"}],"sources":[{"id":"nam18","locator":"1918-10对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1918-11","date":"1918-11","title":"十一点停火之后，和平尚未完成","theaters":["外交","后方"],"countries":["de","uk","fr","us","ah"],"people":["福煦","威廉二世"],"story":["德国革命扩大，威廉二世退位，新的政府承担停战责任。11日，德国代表与协约国签订停战安排，西线于上午十一点停止交火，长期战争终于出现清晰的军事终点。","许多人因此获救，另一些人的伤残、丧亲、饥饿与流亡却不会随钟声消失。停战条款、复员、俘虏回返和封锁问题仍待处理，战后政治边界也尚未谈妥。","战场失败、国内革命与停战签署之间的关系，后来被极端民族主义歪曲。理解真正的因果，需要把军队此前的持续败退、资源困境和盟友瓦解一起看，而不能接受把失败全部归罪于后方的神话。"],"perspectives":[{"country":"de","text":"新政权接下战争遗产，停战责任后来成为政治攻击对象。"},{"country":"fr","text":"本土战事结束，却要面对重建、损失与未来安全安排。"}],"sources":[{"id":"nam18","locator":"1918-11对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"peace","locator":"1918-11对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1919-01","date":"1919-01","title":"巴黎和会：胜利者之间也有不同的和平","theaters":["外交"],"countries":["us","uk","fr","it","cn","jp"],"people":["威尔逊","克列孟梭","劳合·乔治"],"story":["巴黎和会开幕，战后安全、赔偿、领土和国际组织成为议题。法国重视防止德国再次进攻，英国权衡欧洲均势与帝国利益，威尔逊则推动国际联盟和新的和平原则。","这些目标并不总能兼容，战败国与许多弱小民族也没有同等发言权。中国希望解决山东权益问题，却发现战时秘密协议与列强利益仍然有力，战场贡献并没有自动变成谈判平等。"],"perspectives":[{"country":"fr","text":"遭受入侵与破坏的经验，使安全保障成为核心诉求。"},{"country":"cn","text":"期待恢复主权，面对的却是日本和其他强国既有安排。"}],"sources":[{"id":"peace","locator":"1919-01对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"chinaWW1","locator":"1919-01对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww1-1919-06","date":"1919-06","title":"凡尔赛：签下一份条约，没有解决所有问题","theaters":["外交","后方"],"countries":["de","fr","uk","us","cn","jp"],"people":["威尔逊","克列孟梭"],"story":["28日，凡尔赛条约签署，对德国领土、军备、赔偿责任等作出安排，并纳入国际联盟框架。德国社会的不满与各国对安全的追求同时存在，条约不能只用胜利者惩罚或失败者受辱一个角度解释。","中国因山东问题拒绝在对德和约上签字。美国后来也未批准条约加入国际联盟。一战通向二战不是一条注定的直线，还需结合经济危机、法西斯政治、侵略选择与集体安全失效，才能理解其间的变化。"],"perspectives":[{"country":"de","text":"条约争议成为国内政治动员的重要材料，却不能为后来侵略开脱。"},{"country":"cn","text":"拒签体现主权诉求，也显示战后国际秩序的平等承诺存在限度。"}],"sources":[{"id":"peace","locator":"1919-06对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"chinaWW1","locator":"1919-06对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]}]},{"id":"ww2","name":"第二次世界大战","years":"1939—1945","subtitle":"从侵略扩张，到全球抵抗与艰难和平","coverage":"1939年9月—1945年9月，73个月连续；另列1931年以来亚洲与欧洲前史。","intro":"侵略并非不可避免的自然灾害。独裁、种族主义、帝国扩张与集体安全失效，逐步把各地区战争连成全球冲突；抵抗、联盟与社会动员最终击败轴心国，却留下巨大的平民灾难与未解的战后问题。","start":"1939-09","end":"1945-09","default":"1939-09","phases":[["1931-09","前史：侵略的扩张"],["1939-09","欧洲开战与轴心推进"],["1941-06","战争全球化"],["1942-11","转折与同盟合作"],["1944-01","多线反攻"],["1945-06","终战与战后秩序"]],"months":[{"id":"ww2-1931-09","date":"1931-09","title":"从沈阳开始的侵略：亚洲前史不能略去","theaters":["中国","外交"],"countries":["cn","jp"],"people":["张学良"],"story":["9月18日，日本关东军制造柳条湖事件并进攻沈阳，随后扩占中国东北。地方军事行动很快改变整个地区的政治形势，侵略并未因国际社会的交涉而停止。","本卷把1939年9月至1945年9月作为全球大战主时间轴，同时把中国抗战的1931年起点及1937年全面抗战单列前史。不同战争分期需要说明，不能因欧洲开战较晚而让亚洲长期战争消失。"],"perspectives":[{"country":"cn","text":"失土、流亡与抵抗使战争进入东北军民生活。"},{"country":"jp","text":"军部扩张与既成事实侵蚀外交约束，也推动帝国继续走向侵略。"}],"sources":[{"id":"china","locator":"1931-09对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1933-01","date":"1933-01","title":"希特勒上台：侵略与迫害需要追溯政治起点","theaters":["德国","后方"],"countries":["de","fr"],"people":["希特勒"],"story":["30日，希特勒被任命为德国总理。纳粹随后利用国家权力摧毁政治竞争，排斥与迫害犹太人及其他群体，逐步把德国改造成独裁体制。","战争并非1939年突然从无到有。反民主政治、种族主义与扩军政策相互支撑，国家机器既被用于准备对外征服，也被用于针对本国居民的制度性迫害。"],"perspectives":[{"country":"de","text":"国家并非单一意志，政权通过镇压、宣传和组织控制压缩反对空间。"},{"country":"fr","text":"邻国政治转向与军备问题，逐渐改变法国面对的安全环境。"}],"sources":[{"id":"holocaust","locator":"1933-01对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1935-10","date":"1935-10","title":"意大利侵略埃塞俄比亚，集体安全遭考验","theaters":["非洲","外交"],"countries":["it","uk","fr"],"people":["墨索里尼"],"story":["意大利军队入侵埃塞俄比亚，殖民扩张冲击国际联盟维护和平的承诺。制裁和外交讨论未能及时阻止征服，弱国很难仅凭制度承诺获得有效保护。","英国、法国既担心意大利倒向德国，也要顾及各自帝国利益。对侵略的应对因此被利益权衡削弱，这种失败并不意味着战争必然发生，却使继续冒险的代价看起来更低。"],"perspectives":[{"country":"it","text":"法西斯政权以帝国扩张追求声望，侵略给当地造成深重苦难。"},{"country":"uk","text":"制止侵略与维护欧洲联盟之间的矛盾暴露出政策局限。"}],"sources":[{"id":"prewar","locator":"1935-10对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1936-03","date":"1936-03","title":"莱茵兰进军：既成事实再次改变规则","theaters":["欧洲","外交"],"countries":["de","fr","uk"],"people":["希特勒"],"story":["德国军队进入莱茵兰非军事区，挑战战后条约安排。英法没有以军事行动驱离德军，德国在西部边境的战略地位因此改善。","这一行动后来常被写成必然成功的冒险，实际上当时仍有风险与政策选择。其后果在于侵略者从外部反应中判断约束力度，欧洲安全秩序进一步依赖对下一次承诺的相信。"],"perspectives":[{"country":"de","text":"重整军备与违约行动获得政治收益，增强政权继续扩张的信心。"},{"country":"fr","text":"边境安全形势恶化，又受国内政治、联盟与战争恐惧影响。"}],"sources":[{"id":"prewar","locator":"1936-03对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1936-07","date":"1936-07","title":"西班牙内战：欧洲战争的前奏之一","theaters":["欧洲","外交"],"countries":["de","it","su","uk","fr"],"people":["弗朗哥"],"story":["西班牙军人叛乱引发内战，德国、意大利支持叛军，苏联援助共和国，不同国家的志愿者也前来作战。西班牙人的内战由此与欧洲政治对抗交织。","外部介入提供武器、飞机和作战经验，不干涉政策却未能隔绝外国影响。它是理解法西斯扩张、空袭和平民处境的重要前史，但不能把西班牙社会本身的矛盾全部解释为大国代理竞争。"],"perspectives":[{"country":"it","text":"介入内战服务于法西斯影响与地区利益。"},{"country":"su","text":"援助共和国，国际反法西斯合作同时夹杂自身政策目标。"}],"sources":[{"id":"prewar","locator":"1936-07对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1937-07","date":"1937-07","title":"卢沟桥：全面抗战展开","theaters":["中国"],"countries":["cn","jp"],"people":["蒋介石"],"story":["7日夜，日军在卢沟桥附近挑起冲突，中国守军抵抗。危机没有被限制在局部，日军进攻扩大，中国抗战进入全国性、长期性的阶段。","对中国而言，这是国家生存与主权的战争；对日本军部而言，扩大军事行动被寄望于压服中国，却把自身进一步拖入无法迅速结束的战争。此后理解太平洋战争，必须把中国持续抵抗纳入资源与战略背景。"],"perspectives":[{"country":"cn","text":"地方冲突扩为全面战争，需要动员军队、经济与社会。"},{"country":"jp","text":"不断扩大目标，使有限行动逻辑走向长期占领与消耗。"}],"sources":[{"id":"china","locator":"1937-07对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pearl","locator":"1937-07对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1937-08","date":"1937-08","title":"上海会战：把抵抗带到国际都市","theaters":["中国"],"countries":["cn","jp"],"people":["张治中","谢晋元"],"story":["13日起，上海发生大规模交战，中国投入主力，日军通过增兵与登陆扩大攻势。城市、村镇与交通节点反复争夺，工业和人口密集区承受战争破坏。","持续到11月的会战消耗中国精锐，也打破日方迅速迫使中国屈服的设想。难民、工厂迁移与政府西迁，使抗战从战场行动逐渐转为整个社会重组生存条件的过程。"],"perspectives":[{"country":"cn","text":"以持续抵抗争取时间，同时承受军队和城市社会的重大损失。"},{"country":"jp","text":"战场胜利没有转化为中国停止抵抗，侵略范围继续扩大。"}],"sources":[{"id":"china","locator":"1937-08对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":["battle-shanghai-1937"]},{"id":"ww2-1937-12","date":"1937-12","title":"南京陷落与大屠杀：必须正视的战争罪行","theaters":["中国","平民"],"countries":["cn","jp"],"people":["松井石根"],"story":["13日，日军攻占南京，随后对平民及放下武器人员实施大规模杀害，并发生强奸、抢掠等严重暴行。南京大屠杀是有充分史料与战后审判支持的战争罪行，不能被淡化为普通攻城附带事件。","中国政府继续在西部组织抗战，军事失利没有结束国家抵抗。记录屠杀、保护幸存者证言并辨别否认和歪曲，是理解这场战争不可缺少的部分，不能只沿着将领与军队的胜负阅读历史。"],"perspectives":[{"country":"cn","text":"国家抵抗与民众避难并行，丧亲、创伤和流亡延续多年。"},{"country":"jp","text":"军队占领与对平民犯罪必须分别追究，理解行为不等于为其辩解。"}],"sources":[{"id":"china","locator":"1937-12对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nanjing","locator":"1937-12对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1938-03","date":"1938-03","title":"吞并奥地利：扩张以统一之名推进","theaters":["欧洲"],"countries":["de","uk","fr"],"people":["希特勒"],"story":["德国进入并吞并奥地利，纳粹政权扩大领土与资源，并迅速把迫害政策推向当地。所谓民族统一的宣传掩盖了强制、反对者受压和犹太居民遭难。","欧洲其他国家未能有效制止，德国下一步把压力转向捷克斯洛伐克。一次扩张既改变军事位置，也使更多人口进入独裁与种族迫害的统治体系。"],"perspectives":[{"country":"de","text":"政权把兼并包装为民意与民族目标，继续扩大对外野心。"},{"country":"uk","text":"避免再次大战的愿望影响政策，却没有消除扩张带来的安全风险。"}],"sources":[{"id":"prewar","locator":"1938-03对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"holocaust","locator":"1938-03对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1938-04","date":"1938-04","title":"台儿庄告捷，长期抵抗仍需继续","theaters":["中国"],"countries":["cn","jp"],"people":["李宗仁","孙连仲"],"story":["台儿庄战斗中，中国军队以庄内坚守和外线攻击配合，击退日军，振奋全国抗战信心。巷战中的坚持并非孤立行动，需要周围部队牵制、增援和补给共同支撑。","胜利没有终止徐州地区的战事，也没有让日军停止进攻。将局部战果放进长期抗战，才能理解它既显示抵抗能力，又无法独自扭转全部战局的意义。"],"perspectives":[{"country":"cn","text":"胜利提振士气，但必须保存和组织继续作战的力量。"},{"country":"jp","text":"局部受挫未改变侵略政策，随后仍扩大攻势。"}],"sources":[{"id":"china","locator":"1938-04对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":["battle-taierzhuang"]},{"id":"ww2-1938-05","date":"1938-05","title":"怎样理解长期战争：《论持久战》的判断","theaters":["中国","后方"],"countries":["cn","jp"],"people":["毛泽东"],"story":["毛泽东在延安作《论持久战》讲演，反对亡国论和速胜论，分析敌我力量、战争性质与发展阶段，强调通过持久抵抗和人民动员改变力量对比。","这一论述不是预先写好每一场战役的剧本，而是为长期战争提供战略认识。把战场失败、局部胜利、人口动员和外部条件联系起来，才能理解中国为何仍能在日军占领大量城市后继续抵抗。"],"perspectives":[{"country":"cn","text":"正面与敌后作战、社会动员和争取外援共同构成长期抗战条件。"},{"country":"jp","text":"占领城市无法自动消灭抵抗，日方需要承担越来越大的控制和补给成本。"}],"sources":[{"id":"mao38","locator":"1938-05对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1938-09","date":"1938-09","title":"慕尼黑：用谁的领土交换和平","theaters":["欧洲","外交"],"countries":["de","uk","fr"],"people":["希特勒","张伯伦","达拉第"],"story":["英法德意领导人在慕尼黑达成协议，允许德国取得捷克斯洛伐克苏台德地区，受影响国家没有平等参与决定。英法希望通过让步避免战争，捷克斯洛伐克却失去重要防线与资源。","协议带来短暂松懈，没有使希特勒停止扩张。它的教训不仅是后来证明承诺不可信，也在于把弱国安全当作可以由强国处置的筹码，会侵蚀共同规则和防务基础。"],"perspectives":[{"country":"uk","text":"张伯伦希望争取和平和时间，但对德国目标的判断存在严重局限。"},{"country":"de","text":"侵略威胁换得让步，为继续破坏欧洲秩序创造条件。"}],"sources":[{"id":"prewar","locator":"1938-09对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1938-10","date":"1938-10","title":"武汉失守，抗战转入更长的相持","theaters":["中国"],"countries":["cn","jp"],"people":["蒋介石"],"story":["广州、武汉先后失守，中国失去重要交通和经济中心。此前台儿庄等地的胜利并未阻止日军总体推进，局部战果与全国战局的艰难必须同时看到。","政府、学校和工业向内地迁移，正面战场与敌后抵抗继续展开。日本占领更多城市，却仍不能控制广阔社会空间、迫使中国投降，战争由夺取中心城市进一步转为长期消耗。"],"perspectives":[{"country":"cn","text":"迁移与重建成为继续抵抗的基础，社会承受能力受到持久考验。"},{"country":"jp","text":"占领范围扩大，也带来更多守备、运输和统治成本。"}],"sources":[{"id":"china","locator":"1938-10对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1938-11","date":"1938-11","title":"反犹暴行升级，迫害不再隐蔽","theaters":["德国","平民"],"countries":["de","us"],"people":["希特勒"],"story":["9日至10日，纳粹组织针对犹太人的大规模暴行，犹太会堂、商店与住宅遭袭，大批人员被捕。制度性排斥进一步转向公开暴力，受害者生活与逃离空间急剧收缩。","这不是孤立骚乱，而是政权推动迫害的组成部分。把它与后来的占领、隔都、驱逐和屠杀连接起来，才能看清种族灭绝如何通过不断升级的行政与社会暴力形成。"],"perspectives":[{"country":"de","text":"政权和参与者的责任需要辨明，居民面对迫害也有服从、获利、旁观与抵抗等不同选择。"},{"country":"us","text":"难民问题更加迫切，但各国接纳政策仍存在重大限制。"}],"sources":[{"id":"holocaust","locator":"1938-11对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1939-03","date":"1939-03","title":"布拉格被占，慕尼黑承诺破产","theaters":["欧洲","外交"],"countries":["de","uk","fr","pl"],"people":["希特勒","张伯伦"],"story":["德国占领捷克地区，说明扩张已明显超出统一德语人口的说辞。慕尼黑协议没有保护剩余国家，希特勒继续以武力重塑欧洲。","英国随后向波兰作出安全保证，英法政策开始转向更明确的遏制。然而保证怎样转为实际军事帮助仍是问题，波兰的地理位置与盟军部署使承诺和即时救援之间存在距离。"],"perspectives":[{"country":"uk","text":"对德意图的判断发生变化，准备承担更明确的安全义务。"},{"country":"pl","text":"获得外部保证，却仍面临德苏之间的严峻地缘处境。"}],"sources":[{"id":"prewar","locator":"1939-03对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1939-08","date":"1939-08","title":"德苏协定：公开互不侵犯与秘密划界","theaters":["外交"],"countries":["de","su","pl","uk","fr"],"people":["希特勒","斯大林","莫洛托夫"],"story":["23日，德国与苏联签订互不侵犯条约，秘密议定书划分东欧势力范围。德国因此降低进攻波兰时立即两线作战的顾虑，苏联则谋求安全缓冲与自身领土利益。","条约不是两国根本目标一致的证明，更不使随后侵略和占领成为正当行为。英法与苏联未能形成有效协作，波兰等国却将承受强国交易带来的直接后果，欧洲战争的门槛已经极近。"],"perspectives":[{"country":"de","text":"获得暂时的东方保障，准备以武力解决波兰问题。"},{"country":"su","text":"通过协议争取空间与时间，同时参与划分他国领土的安排。"}],"sources":[{"id":"prewar","locator":"1939-08对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1939-09","date":"1939-09","title":"波兰被夹击，欧洲大战爆发","theaters":["欧洲","外交"],"countries":["de","pl","su","uk","fr"],"people":["希特勒","斯大林","张伯伦"],"story":["1日，德国入侵波兰，3日英法对德宣战。德国以空地协同和机动部队迅速推进，波兰军队持续抵抗，但难以及时获得西方盟国直接救援。17日，苏军又从东部进入波兰。","华沙围城、平民逃亡与军事崩溃同时发生，波兰被德苏分割占领。国家被占不等于抵抗终止，流亡政府、地下组织和海外军队随后继续作战，战争也从一场侵略扩展为欧洲多国的长期冲突。"],"perspectives":[{"country":"pl","text":"面临两面进军与盟援不足，保全国家政治和抵抗组织成为后续任务。"},{"country":"uk","text":"宣战意味着承担长期战争，却没有立即改变波兰战场力量对比。"}],"sources":[{"id":"ww2dates","locator":"1939-09对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1939-10","date":"1939-10","title":"占领秩序建立，西线仍在等待","theaters":["欧洲","平民"],"countries":["de","pl","uk","fr"],"people":["希特勒"],"story":["波兰有组织的大规模抵抗在10月初进一步告终，纳粹占领当局开始分区统治、强制迁移与镇压。军事胜利迅速转化为针对社会与人口的统治工程，犹太人及其他居民受到越来越严厉的迫害。","西线英法与德国未展开决定性陆战，后来被称为假战时期。但海上作战、经济封锁和军队集结都在继续，表面安静不是和平，只是在为下一阶段冲突积累力量。"],"perspectives":[{"country":"de","text":"占领不只是驻军，而是实施掠夺、迫害与人口政策。"},{"country":"fr","text":"防御和动员持续进行，却仍需判断德国下一步主攻方向。"}],"sources":[{"id":"ww2dates","locator":"1939-10对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"holocaust","locator":"1939-10对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1939-11","date":"1939-11","title":"冬季战争与美国中立法的变化","theaters":["东线","外交"],"countries":["su","us","uk"],"people":["斯大林","罗斯福"],"story":["30日，苏联进攻芬兰，试图以军事手段改变边境安全条件。随后的芬兰抵抗、严寒地形和苏军组织问题，使这场战争比进攻者预想的困难，强国的兵力优势并不保证低成本取胜。","美国修改中立法，允许在现购自运条件下向交战国出售武器。它仍未参战，却逐步从严格限制转向为英法获得物资提供渠道，法律中立与政策倾向开始分离。"],"perspectives":[{"country":"su","text":"军事行动暴露训练和组织缺陷，也造成新的国际压力。"},{"country":"us","text":"避免直接参战的同时，扩大对抗侵略国家的物资支持空间。"}],"sources":[{"id":"neutral","locator":"1939-11对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"winter","locator":"1939-11对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1939-12","date":"1939-12","title":"拉普拉塔河口：海上战争已遍及远方","theaters":["海战","东线"],"countries":["uk","de","su"],"people":["朗斯多夫"],"story":["英国等舰艇在南大西洋追击德国装甲舰施佩伯爵海军上将号，交战后该舰进入蒙得维的亚，最终自沉。远洋袭商与追击把中立港口、情报和外交都卷入海战。","芬兰战场上，苏军继续付出高昂代价，冬季战争尚未结束。欧洲西线的等待不能代表整个世界，海路与北方边境的战事正在塑造各国对自身能力的判断。"],"perspectives":[{"country":"uk","text":"保护全球贸易航线，需要分散部署并依靠情报协同。"},{"country":"de","text":"袭商舰的活动能制造压力，却难以长期对抗广泛的海上追踪体系。"}],"sources":[{"id":"sea","locator":"1939-12对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"winter","locator":"1939-12对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1940-01","date":"1940-01","title":"配给开始，漫长战争进入餐桌","theaters":["后方","东线"],"countries":["uk","de","su"],"people":["张伯伦"],"story":["英国开始实施部分食品配给，把有限进口与国内供应纳入更有组织的分配。对居民而言，战争不再只是报纸上的战报，而是购买、劳动和家庭生活方式的改变。","芬兰方面继续抵抗苏军，英法讨论援助与北欧战略。军事与资源问题交织，使斯堪的纳维亚的重要性上升；所谓等待期，正酝酿新的战场。"],"perspectives":[{"country":"uk","text":"公平分配和持续供给关系到社会能否接受长期动员。"},{"country":"su","text":"前线困难迫使军队调整战法，依靠更集中的火力与兵力推进。"}],"sources":[{"id":"winter","locator":"1940-01对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"home","locator":"1940-01对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1940-02","date":"1940-02","title":"北欧冰雪中的突破与海上冲突","theaters":["东线","海战"],"countries":["su","uk","de"],"people":["斯大林"],"story":["苏军集中力量进攻芬兰防线，逐步取得突破，芬兰继续作战的条件越来越困难。战场经验说明，初期失败不能简单等同于军队此后始终无能。","英国海军在挪威水域截获德国补给船阿尔特马克号并解救被俘船员，引发中立与海上行动争议。德国和英国都更加关注挪威沿岸与运输线，北欧的中立处境进一步受压。"],"perspectives":[{"country":"su","text":"以增援和战术调整扭转战场，但损失与外交代价已经发生。"},{"country":"uk","text":"海上行动的军事收益，也会牵动中立国和德国的下一步判断。"}],"sources":[{"id":"winter","locator":"1940-02对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"sea","locator":"1940-02对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1940-03","date":"1940-03","title":"芬兰议和，战争危机却未解除","theaters":["东线","中国"],"countries":["su","cn","jp"],"people":["斯大林","汪精卫"],"story":["苏芬签署莫斯科和约，芬兰保住国家独立，却割让领土并承担大规模人口迁移。战争在军事优势与国家生存之间形成妥协，边境居民必须承受地图改动的现实后果。","中国南京建立汪精卫伪政权，日本试图把军事占领转化为政治控制。中国的抗战继续，合作政权的存在并不意味着被占领社会已经接受侵略，抵抗与统治争夺进入日常治理层面。"],"perspectives":[{"country":"su","text":"取得部分安全与领土目标，战争暴露的问题仍待解决。"},{"country":"cn","text":"侵略者扶植政权加剧政治分裂，但未能结束正面及敌后抵抗。"}],"sources":[{"id":"winter","locator":"1940-03对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"china","locator":"1940-03对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1940-04","date":"1940-04","title":"丹麦、挪威遭侵：战争绕过预想正面","theaters":["欧洲","海战"],"countries":["de","uk","fr"],"people":["希特勒"],"story":["9日，德国进攻丹麦和挪威，以空降、海运和地面行动夺取要点。英法随后介入，挪威战役把港口、铁矿运输与海上补给的战略意义集中呈现。","盟军在北欧的行动没有迅速扭转局面，德国也付出舰船损失。战争表明，控制狭长海岸与远距离增援极为复杂，政治上宣布援助并不等于已有可执行的军事方案。"],"perspectives":[{"country":"de","text":"意在保障北方战略位置及运输，仍需承担长期占领成本。"},{"country":"uk","text":"行动失误引发国内批评，为政府更替积累压力。"}],"sources":[{"id":"ww2dates","locator":"1940-04对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1940-05","date":"1940-05","title":"阿登突破与敦刻尔克：退回去才能继续打","theaters":["西线"],"countries":["de","fr","uk"],"people":["希特勒","丘吉尔","古德里安"],"story":["10日，德国攻击荷兰、比利时等国及法国，装甲部队经阿登推进，在色当方向突破，迅速奔向英吉利海峡。进入比利时的盟军主力面临被切断退路的危险，法国指挥反应与通信困难使危机扩大。","丘吉尔在英国出任首相。月底，英法军队向敦刻尔克收缩，海军与各类船只开始撤运，地面和空中掩护使大量人员得以脱离；撤退延续到6月。","敦刻尔克保存了继续作战的人力，却损失大量装备，也未能挽救法国整体战局。它既是灾难中的组织成功，也是盟军必须重新学习现代机动作战的一次沉重失败。"],"perspectives":[{"country":"uk","text":"保存军队后仍需重建防御，撤离成功并非已经赢得战争。"},{"country":"fr","text":"主力被分割与后方失序叠加，国家防御迅速恶化。"}],"sources":[{"id":"ww2dates","locator":"1940-05对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"dunkirk","locator":"1940-05对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1940-06","date":"1940-06","title":"法国停战，继续抵抗出现两条道路","theaters":["西线","外交"],"countries":["fr","de","uk","it"],"people":["贝当","戴高乐","墨索里尼"],"story":["德军进入巴黎，法国政府在军事崩溃中选择停战，22日签订对德协定。意大利也加入战争，欧洲力量格局骤变，英国失去重要大陆盟友。","贝当政权在维希建立统治并走向合作，戴高乐从伦敦号召继续抵抗。法国既有占领与合作，也有流亡力量和地下抵抗，不能以政府停战概括所有法国人的选择。"],"perspectives":[{"country":"fr","text":"停战把国家带入占领、合作与抵抗并存的局面。"},{"country":"uk","text":"面对更直接的空袭和入侵威胁，继续战争需要守住本土与海运。"}],"sources":[{"id":"ww2dates","locator":"1940-06对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1940-07","date":"1940-07","title":"不列颠上空与盟友之间的裂痕","theaters":["空战","海战"],"countries":["uk","de","fr"],"people":["丘吉尔","戈林"],"story":["德国空军逐步扩大对英国的攻击，不列颠空战展开。雷达、地面观察、指挥网络、飞行员轮换和飞机维修共同支撑英国防御，不能把胜负只归功于某一种战斗机。","英国攻击米尔斯克比尔港法国舰队，防止军舰落入敌手的考虑造成昔日盟友人员伤亡。坚持对德作战与处理法国舰队的安全忧虑交织，也留下深刻政治裂痕。"],"perspectives":[{"country":"uk","text":"防御本土同时承担艰难且有争议的海军决策。"},{"country":"fr","text":"法国不同政治力量对英国的行动作出不同反应，合作与抵抗之路更加复杂。"}],"sources":[{"id":"ww2dates","locator":"1940-07对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"sea","locator":"1940-07对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1940-08","date":"1940-08","title":"空战高峰与华北交通破袭","theaters":["空战","中国"],"countries":["uk","de","cn","jp"],"people":["休·道丁","彭德怀"],"story":["德国空军加强攻击英国机场、设施与航空力量，英国战斗机部队在高强度出动中维持防御。损失必须通过训练、生产和维修补足，空战同样是一场组织与资源的较量。","20日，八路军发起百团大战，破袭华北铁路和据点体系，试图削弱日军分割根据地的能力。正面空战与敌后交通战发生在不同空间，却都指向持续作战依赖的运输和组织网络。"],"perspectives":[{"country":"uk","text":"保护指挥与航空力量，是阻止德国取得制空优势的关键。"},{"country":"cn","text":"破袭交通为敌后抵抗争取空间，也会面对日军报复性进攻。"}],"sources":[{"id":"ww2dates","locator":"1940-08对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"china","locator":"1940-08对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":["battle-hundred-regiments"]},{"id":"ww2-1940-09","date":"1940-09","title":"伦敦遭轰炸，三国同盟成形","theaters":["空战","外交","亚洲"],"countries":["de","uk","it","jp","cn"],"people":["希特勒","丘吉尔"],"story":["德国把轰炸重点更多转向伦敦等城市，平民避难、消防与救援成为日常。英国未被迫退出战争，德国跨海入侵计划被推迟，空袭却持续制造伤亡与破坏。","德意日签订三国同盟条约，日本又向法属印度支那北部推进。轴心国并非一支统一指挥的军队，但各自扩张开始更紧密牵动欧洲、东亚与美国的政策。"],"perspectives":[{"country":"uk","text":"社会韧性建立在防空、救援和供应组织之上，不能浪漫化居民承受的恐惧。"},{"country":"jp","text":"借欧洲殖民宗主国受挫扩大南方影响，也加剧美日矛盾。"}],"sources":[{"id":"ww2dates","locator":"1940-09对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pearl","locator":"1940-09对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1940-10","date":"1940-10","title":"意大利攻希腊，扩大战争未必带来收益","theaters":["欧洲","空战"],"countries":["it","de","uk"],"people":["墨索里尼"],"story":["意大利从阿尔巴尼亚方向进攻希腊，希望取得独立军事成果。希腊抵抗和地形、补给问题使进攻受挫，意军很快面临反击，轴心国在巴尔干制造了新的战略负担。","英国继续承受轰炸，不列颠空战的主要白昼阶段渐告结束，夜间空袭仍未停止。没有被入侵与没有遭受灾难，是两件不同的事。"],"perspectives":[{"country":"it","text":"政治声望目标超出准备与后勤能力，进攻反使自身陷入困境。"},{"country":"uk","text":"本土防御稳定后仍需考虑地中海、希腊与北非的援助分配。"}],"sources":[{"id":"ww2dates","locator":"1940-10对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1940-11","date":"1940-11","title":"塔兰托夜袭与城市火灾","theaters":["海战","空战"],"countries":["uk","it","de"],"people":["安德鲁·坎宁安"],"story":["英国舰载机夜袭塔兰托，重创意大利舰艇，展示航空兵威胁停泊舰队的能力。地中海补给与舰队行动条件因此变化，但这并未立即结束意大利海军的作用。","德国猛烈轰炸考文垂，城市工业与居民区遭破坏。将工厂、交通与居民生活混在一起的空袭，显示总体战如何消解前线与后方的界线，军事效果与伦理代价必须同时审视。"],"perspectives":[{"country":"uk","text":"既运用航空兵攻击敌舰，也在本土承受空袭。"},{"country":"it","text":"舰艇损失压缩行动选择，地中海战争更依赖基地与补给保障。"}],"sources":[{"id":"sea","locator":"1940-11对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"home","locator":"1940-11对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1940-12","date":"1940-12","title":"北非反攻与“兵工厂”的承诺","theaters":["北非","后方"],"countries":["uk","it","us"],"people":["韦维尔","罗斯福"],"story":["英军在北非发动罗盘行动，击退进入埃及的意军，攻势随后向利比亚推进。沙漠战看似适合机动，燃料、运输与港口却始终限制军队能走多远。","罗斯福向美国公众强调为抵抗轴心国提供军需的重要性。英国财力吃紧，美国如何在尚未参战时扩大援助，逐渐成为战略问题，战场得失与跨大西洋生产线开始更紧密连接。"],"perspectives":[{"country":"it","text":"北非失利迫使其向德国寻求更多军事支持。"},{"country":"us","text":"援助理念向大规模制度安排发展，为此后的租借法铺路。"}],"sources":[{"id":"sea","locator":"1940-12对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"lend","locator":"1940-12对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1941-01","date":"1941-01","title":"北非推进与皖南事变：盟友并非没有裂痕","theaters":["北非","中国"],"countries":["uk","it","cn","jp"],"people":["韦维尔","叶挺"],"story":["英联邦军在北非继续推进，巴迪亚等据点失守，意军危机加深。胜利打开更多空间，也使英国面临是否继续追击、还是把兵力调往其他战场的选择。","中国发生皖南事变，新四军部队遭国民党军攻击，叶挺被扣。共同抗日并未消除内部矛盾，理解中国战场既要看合作抗敌，也要看关系破裂如何伤害共同抵抗。"],"perspectives":[{"country":"uk","text":"北非成果需要与巴尔干援助等任务争夺兵力。"},{"country":"cn","text":"抗战统一战线遭严重冲击，但对日作战仍在继续。"}],"sources":[{"id":"nz","locator":"1941-01对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"china","locator":"1941-01对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1941-02","date":"1941-02","title":"隆美尔抵达，沙漠战局重新打开","theaters":["北非","海战"],"countries":["de","it","uk"],"people":["隆美尔","韦维尔"],"story":["德国派部队进入北非支援意大利，隆美尔抵达利比亚。英国此前的胜利没有让战区永久稳定，新的指挥、装甲力量与空中支持开始改变对抗条件。","地中海运输仍决定双方补给。沙漠上的快速推进离不开燃油、零件和港口，任何将领的个人声望都不能代替这些条件；此后反复进退，将不断证明这一点。"],"perspectives":[{"country":"de","text":"支援盟友也意味着承担另一条补给困难的战线。"},{"country":"uk","text":"需要在既有胜利后防止力量分散，保持北非后勤和预备队。"}],"sources":[{"id":"nz","locator":"1941-02对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"sea","locator":"1941-02对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1941-03","date":"1941-03","title":"租借法：尚未参战的国家改变力量平衡","theaters":["外交","后方"],"countries":["us","uk","cn","su"],"people":["罗斯福"],"story":["11日，美国租借法生效，使政府能够向对其安全重要的国家提供物资。英国无力长期以现金购买军需的问题，获得新的制度性解决途径，援助随后也扩及中国和苏联等国。","这不仅是运送武器，还包括车辆、粮食、原材料和运输支持。援助必须穿越海洋和边境才能变成战斗力，生产、航运和接收体系将成为联盟作战的重要基础。"],"perspectives":[{"country":"us","text":"未正式参战却已越来越深地支持抗击轴心国。"},{"country":"uk","text":"获得长期物资来源，但航线防护仍决定援助能否抵达。"}],"sources":[{"id":"lend","locator":"1941-03对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1941-04","date":"1941-04","title":"巴尔干遭侵，德苏中立与准备并行","theaters":["欧洲","北非","外交"],"countries":["de","uk","it","su","jp"],"people":["希特勒","隆美尔"],"story":["德国进攻南斯拉夫和希腊，盟军再度后撤，英国在地中海东部的处境恶化。北非德意军反攻并围困托布鲁克，英国需要在多个危险方向同时应对。","苏联与日本签订中立条约，暂时降低彼此边境风险。两个国家各有战略重点，协定并不意味着全球冲突缓和，反而帮助它们分别处理西部与南方问题。"],"perspectives":[{"country":"uk","text":"巴尔干、北非和海路压力叠加，兵力调配更加艰难。"},{"country":"su","text":"希望稳定远东，同时仍需判断德国在西部边境集结的意图。"}],"sources":[{"id":"nz","locator":"1941-04对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"yugoslavia","locator":"1941-04对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pearl","locator":"1941-04对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1941-05","date":"1941-05","title":"克里特空降与俾斯麦号沉没","theaters":["欧洲","海战"],"countries":["de","uk"],"people":["希特勒","丘吉尔"],"story":["德军空降克里特岛，付出严重损失后夺取控制。空降能越过海面障碍，却仍需夺取机场、运入增援与维持补给；新型作战方式的威力与脆弱同时显露。","德国战列舰俾斯麦号进入大西洋后遭英国舰队追击并沉没。英国失去胡德号等损失同样沉重，海上较量并未因一艘主力舰的终结而结束，潜艇战争仍持续威胁航运。"],"perspectives":[{"country":"de","text":"海空行动取得部分成果，却损失难以轻易补充的力量。"},{"country":"uk","text":"保护航线和基地需要跨海空协作，海军优势并不意味着没有脆弱处。"}],"sources":[{"id":"nz","locator":"1941-05对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"sea","locator":"1941-05对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1941-06","date":"1941-06","title":"巴巴罗萨：侵略把欧洲推入更深灾难","theaters":["东线","平民"],"countries":["de","su"],"people":["希特勒","斯大林","朱可夫"],"story":["22日，德国及其盟军入侵苏联，撕毁互不侵犯安排。苏军在突袭、指挥混乱与部署问题下遭受大规模损失，许多部队被围，德军向列宁格勒、莫斯科与乌克兰方向推进。","这场战争不只是军队争夺阵地。纳粹对苏联的战争与种族主义、掠夺粮食和消灭所谓敌人的计划相连，战俘、犹太人和广大平民面临极端暴力，特别行动队在占领区实施大规模枪杀。","苏联开始搬迁工业、动员兵员并重建战线。德军的初期胜利并未消除距离、交通与补给问题，军事突进和苏联持续抵抗之间的拉锯，将使德国速胜计划逐步失效。"],"perspectives":[{"country":"su","text":"国家生存危机要求动员和调整，早期失误造成巨大代价。"},{"country":"de","text":"以征服与种族政策推动战争，无法用普通安全竞争解释或开脱。"}],"sources":[{"id":"ww2dates","locator":"1941-06对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"holocaust","locator":"1941-06对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1941-07","date":"1941-07","title":"向基辅推进，日本南进引发制裁","theaters":["东线","亚洲","外交"],"countries":["de","su","jp","us","cn"],"people":["希特勒","斯大林","近卫文麿"],"story":["德军向苏联纵深推进，斯摩棱斯克等地交战使攻势继续付出损失。苏联防线反复重组，撤退与抵抗同时进行，战争逐渐显露超出短期计划的规模。","日本进入法属印度支那南部，美国冻结日本资产，石油供应受到严格限制。日方把继续侵略与获取南方资源连在一起，却不愿通过结束侵华来化解危机，美日谈判因而越来越难。"],"perspectives":[{"country":"jp","text":"资源压力与既有侵略目标冲突，军部逐渐倾向进一步扩大战争。"},{"country":"us","text":"以经济手段遏止扩张，制裁又促使日本重新计算开战风险。"}],"sources":[{"id":"ww2dates","locator":"1941-07对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pearl","locator":"1941-07对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1941-08","date":"1941-08","title":"大西洋宪章与围城逼近","theaters":["外交","东线"],"countries":["uk","us","su","de"],"people":["罗斯福","丘吉尔"],"story":["罗斯福与丘吉尔会晤，发表大西洋宪章，提出战后秩序的共同原则。美国仍未正式参战，双方已尝试说明战争为何而打、结束后应建立怎样的制度。","东线德国继续推进，列宁格勒面临合围危险。关于民族自决的原则与英国等国殖民现实之间仍有矛盾；盟国的道义目标需要与其实际政策对照，而不能只把宣言当作已经实现的事实。"],"perspectives":[{"country":"us","text":"通过共同原则支持英国，同时顾及国内对直接参战的顾虑。"},{"country":"uk","text":"希望获得更牢固的美国支持，却不愿全面放弃帝国利益。"}],"sources":[{"id":"atlantic","locator":"1941-08对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"ww2dates","locator":"1941-08对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1941-09","date":"1941-09","title":"列宁格勒被围，基辅与巴比亚尔","theaters":["东线","平民"],"countries":["su","de"],"people":["斯大林","朱可夫"],"story":["列宁格勒陆上通道遭切断，长期围城开始，居民此后承受饥饿、寒冷与轰炸。基辅方向苏军遭到重大围歼，军事损失与乌克兰占领区的灾难同时扩大。","29日至30日，纳粹在基辅附近巴比亚尔大规模杀害犹太人。这些枪杀不是与战线无关的偶然暴行，而是侵略和种族灭绝政策在占领区实施的直接体现。"],"perspectives":[{"country":"su","text":"一面组织前线抵抗，一面面对城市供给和人口生存危机。"},{"country":"de","text":"军队推进与党卫队、警察等杀戮机制相互联系，责任不能只推给少数个人。"}],"sources":[{"id":"ww2dates","locator":"1941-09对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"holocaust","locator":"1941-09对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1941-10","date":"1941-10","title":"莫斯科方向与东京内阁：两场决策逼近终点","theaters":["东线","外交"],"countries":["de","su","jp","us"],"people":["希特勒","斯大林","东条英机"],"story":["德军发动台风行动，试图攻取莫斯科，苏军在维亚济马等地遭受严重损失。首都方向的危机迫使苏联加紧组织防御，泥泞、道路与日渐拉长的补给线也限制德军。","东条英机在日本组阁，美日交涉继续，却无法调和侵华、撤军与资源政策上的冲突。两个战场看似相距遥远，实际上都显示以扩大军事行动解决既有困境的危险。"],"perspectives":[{"country":"su","text":"必须守住政治与交通中心，并把新部队投入防线。"},{"country":"jp","text":"政府更替未改变侵略目标的根本约束，外交选择继续收窄。"}],"sources":[{"id":"ww2dates","locator":"1941-10对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pearl","locator":"1941-10对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1941-11","date":"1941-11","title":"莫斯科最后突击，北非再度反攻","theaters":["东线","北非"],"countries":["de","su","uk","jp","us"],"people":["朱可夫","隆美尔"],"story":["德军重新向莫斯科推进，却在损失、补给和冬季条件下越来越难维持攻势。苏军的抵抗、工业转移与增援同样关键，不能把德国受阻只归因于天气。","英国在北非发动十字军行动，争取解托布鲁克之围。太平洋方向，日本舰队已驶向珍珠港，谈判仍在进行，外交表面与军事准备之间出现危险反差。"],"perspectives":[{"country":"de","text":"在未能速胜后仍试图取得决定性结果，部队承受力逼近极限。"},{"country":"uk","text":"重新争夺北非主动，同时要准备应对远东风险。"}],"sources":[{"id":"nz","locator":"1941-11对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"ww2dates","locator":"1941-11对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pearl","locator":"1941-11对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1941-12","date":"1941-12","title":"莫斯科反攻、珍珠港与真正全球化的战争","theaters":["东线","太平洋","外交"],"countries":["su","de","jp","us","uk","cn"],"people":["罗斯福","山本五十六","朱可夫","丘吉尔"],"story":["苏军在莫斯科方向反攻，击退德军，德国无法在1941年结束对苏战争。几乎同时，7日日本袭击夏威夷珍珠港；按亚洲当地时间，8日前后日军又向马来亚、香港、菲律宾等地展开进攻。","美国对日宣战，德国、意大利随后对美宣战，中国正式对日、德、意宣战，欧洲与亚洲战争更加紧密连成全球冲突。珍珠港重创美国部分舰艇，却没有摧毁其工业与长期动员能力。","日本希望通过突袭和建立广阔防御圈迫使对手妥协，实际上唤起了资源更强大的敌手。此后应同时阅读太平洋舰队作战、中国长期抵抗、苏德陆战与跨大西洋补给，才能理解联盟如何形成合力。"],"perspectives":[{"country":"us","text":"从援助者转为正式交战国，需要同时制定欧洲与太平洋战略。"},{"country":"cn","text":"长期抗战进入更广泛的同盟合作，外援机会增加，但运输与协调仍受限制。"}],"sources":[{"id":"ww2dates","locator":"1941-12对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pearl","locator":"1941-12对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1942-01","date":"1942-01","title":"联合国家宣言与万湖会议","theaters":["外交","平民"],"countries":["us","uk","su","cn","de","jp"],"people":["罗斯福","丘吉尔","海德里希"],"story":["1日，中美英苏等26国签署联合国家宣言，承诺共同对抗轴心国、不单独媾和。联盟开始形成政治框架，但各国对优先战场和战后利益仍有分歧。","20日，纳粹官员在万湖会议上协调驱逐与屠杀欧洲犹太人的行政合作。大规模杀戮此前已经进行，会议并不是种族灭绝突然开始的唯一决策点，而是扩大并组织犯罪的重要环节。"],"perspectives":[{"country":"cn","text":"成为共同宣言签署国之一，国际地位提升与战场困境同时存在。"},{"country":"de","text":"官僚协调使杀戮跨部门运转，行政语言掩盖不了犯罪实质。"}],"sources":[{"id":"wannsee","locator":"1942-01对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1942-01对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1942-02","date":"1942-02","title":"新加坡陷落，日裔美国人遭强制拘禁","theaters":["亚洲","后方"],"countries":["jp","uk","us"],"people":["山下奉文","珀西瓦尔","罗斯福"],"story":["15日，新加坡守军向日军投降，英国在东南亚遭受重大失败。海军基地声望无法弥补陆上防御、空中力量和指挥判断的缺陷，殖民统治的不可战胜形象受到打击。","美国总统签署9066号行政命令，此后大量日裔居民被迫迁离和拘禁。战争恐惧、种族偏见与国家权力结合，损害了许多公民的权利，反法西斯战争中的盟国内部同样存在必须反思的不义。"],"perspectives":[{"country":"uk","text":"必须重建远东防线，也面临殖民威信动摇。"},{"country":"us","text":"动员战争不应成为以族裔代替个体证据、剥夺权利的理由。"}],"sources":[{"id":"nz","locator":"1942-02对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"home","locator":"1942-02对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1942-03","date":"1942-03","title":"仰光失守，通往中国的道路被切断","theaters":["亚洲","中国"],"countries":["jp","uk","cn","us"],"people":["史迪威","蒋介石"],"story":["日军进入仰光，缅甸战局恶化，中国远征军与英军共同作战。中国对外运输依赖的缅甸通道受到威胁，战区之间的物资联系成为同盟作战的现实难题。","麦克阿瑟离开菲律宾转赴澳大利亚，残余守军仍继续抵抗。撤出指挥官与留在阵地的人员有着不同命运，战略重组不能抹去战俘与当地居民随后承受的暴力。"],"perspectives":[{"country":"cn","text":"必须在援缅、保卫运输线与本土作战之间分配有限力量。"},{"country":"jp","text":"快速推进扩大占领范围，也把补给线和守备任务拉得更长。"}],"sources":[{"id":"nz","locator":"1942-03对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"china","locator":"1942-03对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1942-04","date":"1942-04","title":"巴丹投降与杜立特空袭","theaters":["太平洋","中国"],"countries":["us","jp","cn"],"people":["杜立特","麦克阿瑟"],"story":["巴丹守军投降后，战俘遭受死亡行军等严重虐待。军事失败之后的人道灾难，是理解日本占领与军队责任不可分割的一部分。","18日，美军轰炸机从航母起飞空袭日本，随后飞向中国方向。行动提升美国士气，军事破坏有限，却带来深远反应；中国部分地区又遭日军报复性军事行动与暴行，战争的象征收益与他处承担的代价并不对称。"],"perspectives":[{"country":"us","text":"以有限突袭争取士气和主动，但无法单靠一次行动改变战局。"},{"country":"cn","text":"援助飞行员与承受报复的经历，体现盟国行动后果可能由不同群体分担。"}],"sources":[{"id":"nz","locator":"1942-04对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pacific","locator":"1942-04对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1942-05","date":"1942-05","title":"珊瑚海与缅甸撤退：海路被拦，陆路仍险","theaters":["太平洋","亚洲"],"countries":["us","jp","uk","cn"],"people":["尼米兹","史迪威"],"story":["珊瑚海海战中，美日航母航空兵交战，日本从海上夺取莫尔兹比港的计划受阻。舰队可以在彼此不直接目视的情况下作战，侦察与飞机调度成为核心。","缅甸盟军继续撤退，中国部队一部分退入印度，另一部分艰难回国，运输线中断加重中国处境。海上的一次阻击，并没有立即解除陆地盟友的困境。"],"perspectives":[{"country":"us","text":"航母成为阻止日军推进的重要工具，损失仍需工业体系补充。"},{"country":"cn","text":"远征失利与交通切断，使后方补给和作战协调更为艰难。"}],"sources":[{"id":"nz","locator":"1942-05对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pacific","locator":"1942-05对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"china","locator":"1942-05对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1942-06","date":"1942-06","title":"中途岛与托布鲁克：转折并非同时发生","theaters":["太平洋","北非"],"countries":["us","jp","uk","de","it"],"people":["尼米兹","南云忠一","隆美尔"],"story":["美方依据通信情报部署，中途岛交战中击沉日本四艘航母，自身也损失约克城号等力量。航空兵的搜索、连续出击与关键时机交织，使日本试图诱歼美国舰队的计划反遭重创。","北非德意军却在同月攻占托布鲁克并向埃及推进，英国面临新的严重危机。一个战场的胜利不能被直接写成全球局势已全面逆转，盟国仍需处理不同方向彼此矛盾的战报。"],"perspectives":[{"country":"jp","text":"航母和训练有素的人员损失，削弱持续扩张能力。"},{"country":"uk","text":"必须守住埃及方向，补救指挥和补给上的危机。"}],"sources":[{"id":"nz","locator":"1942-06对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pacific","locator":"1942-06对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":["battle-midway-1942"]},{"id":"ww2-1942-07","date":"1942-07","title":"斯大林格勒方向与第一次阿拉曼","theaters":["东线","北非"],"countries":["su","de","uk","it"],"people":["斯大林","保卢斯","奥金莱克"],"story":["德军夏季攻势向苏联南部展开，目标牵涉高加索石油与伏尔加交通。扩大目标使兵力分散，苏军后撤中重新设防，斯大林格勒逐渐成为关键焦点。","北非英国在阿拉曼方向遏止德意军推进，通向埃及腹地的道路未被打开。两个战场都说明，进攻的地理终点还没有到达，补给与兵力的承受终点却可能先行出现。"],"perspectives":[{"country":"de","text":"企图同时夺取资源与交通中心，却面临长距离补给压力。"},{"country":"su","text":"在严重危机中继续动员，城市守备与外围重组同时进行。"}],"sources":[{"id":"ww2dates","locator":"1942-07对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1942-07对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1942-08","date":"1942-08","title":"瓜达尔卡纳尔登陆，伏尔加河畔战斗逼近","theaters":["太平洋","东线"],"countries":["us","jp","su","de"],"people":["范德格里夫","崔可夫"],"story":["7日，美军登陆瓜达尔卡纳尔等岛屿，争夺机场和海上交通。战斗很快由登陆成功转为长期补给与岛周海空争夺，驻岛士兵能否获得粮弹成为核心。","斯大林格勒遭猛烈空袭，城市破坏和居民苦难迅速扩大，德军逐步逼近城区。海岛与工业城市的战斗形态不同，却都把军事目标与平民生活彻底搅在一起。"],"perspectives":[{"country":"us","text":"首次重要反攻需要持续运输支持，登陆并非战役结束。"},{"country":"su","text":"保卫城市与转运居民、伤员、部队面临巨大压力。"}],"sources":[{"id":"ww2dates","locator":"1942-08对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pacific","locator":"1942-08对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1942-09","date":"1942-09","title":"街道与丛林：攻势陷入近距离消耗","theaters":["东线","太平洋"],"countries":["su","de","us","jp"],"people":["崔可夫","保卢斯"],"story":["斯大林格勒市区出现持续街巷和工厂争夺，苏军依靠伏尔加河通道维持兵员与物资。德军即使占住许多街区，也未能把城市抵抗完全消灭。","瓜岛日军反复攻击美军阵地，在运输困难与作战失利中不断消耗。远距离指挥把小范围战斗当作必须赢得的关键，双方都被迫向局部投入越来越多资源，消耗本身开始改变全局。"],"perspectives":[{"country":"su","text":"守住有限阵地为外围筹划反攻争取时间。"},{"country":"jp","text":"低估守军与补给困难，增援未能形成可持续优势。"}],"sources":[{"id":"ww2dates","locator":"1942-09对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pacific","locator":"1942-09对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1942-10","date":"1942-10","title":"阿拉曼反攻：准备工作走到前台","theaters":["北非","太平洋"],"countries":["uk","de","it","us","jp"],"people":["蒙哥马利","隆美尔"],"story":["23日，英国第八集团军在阿拉曼发起进攻。集中补给、炮兵、工程破障与兵力组织，为突破德意防线提供基础，胜利不能只用两名将领的个人较量解释。","瓜岛海空战仍在继续，双方航母与舰船继续遭受损失。到这一阶段，轴心国还能进行激烈作战，却越来越难以补充人员、航空兵与航运损失，持续生产和训练体系的差距开始显现。"],"perspectives":[{"country":"uk","text":"准备和后勤让兵力优势有条件转为实际成果。"},{"country":"de","text":"北非防御受到持续压力，资源补充又与欧洲其他战场竞争。"}],"sources":[{"id":"nz","locator":"1942-10对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pacific","locator":"1942-10对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1942-11","date":"1942-11","title":"三个战场的转向：包围、登陆与海上补给","theaters":["东线","北非","太平洋"],"countries":["su","de","uk","us","it","jp"],"people":["朱可夫","华西列夫斯基","艾森豪威尔","蒙哥马利"],"story":["阿拉曼胜利后德意军后撤，8日英美在法属北非登陆，轴心国面临东西夹击。维希法国当局的立场变化、德国占领法国南部等后果，又使政治与军事局势一同改变。","19日，苏军发起天王星行动，突破斯大林格勒外围轴心国防线，23日前后合围德军第六集团军。市内争夺还在继续，德军却由争取占领者变成需要解围和空运救援的被围者。","瓜岛附近海战也削弱日本维持岛上大规模进攻的能力。三条战线的变化相互加强，但都不是战争结束：盟国仍需把局部主动转为长期协同和连续攻势。"],"perspectives":[{"country":"su","text":"将城市坚守转化为外围包围，战略主动开始明显变化。"},{"country":"us","text":"首次大规模进入北非，需要在实战中学习联盟协调与陆战。"}],"sources":[{"id":"ww2dates","locator":"1942-11对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1942-11对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":["battle-stalingrad"]},{"id":"ww2-1942-12","date":"1942-12","title":"解围失败，反应堆启动：战争的两种未来","theaters":["东线","后方"],"countries":["de","su","us"],"people":["曼施坦因","保卢斯","费米"],"story":["德军尝试从外线解救斯大林格勒被围部队，未能接通包围圈；苏军继续扩大压力，空运也不足以维持被围大军。坚持守城的命令，把士兵命运与越来越不现实的期待绑在一起。","芝加哥出现受控核链式反应的重要实验进展，为曼哈顿计划提供基础。此时核武器尚未用于战场，科研、工业和秘密国家工程却已开始构成另一条将深刻影响战争结局与战后安全的线索。"],"perspectives":[{"country":"de","text":"政治命令、军事判断和补给现实之间的冲突愈加尖锐。"},{"country":"us","text":"投入巨大科研资源的同时，也将面临这种武器如何使用的道德与政治问题。"}],"sources":[{"id":"nz","locator":"1942-12对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"atomic","locator":"1942-12对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1943-01","date":"1943-01","title":"卡萨布兰卡与列宁格勒通道","theaters":["外交","东线"],"countries":["us","uk","su","de"],"people":["罗斯福","丘吉尔"],"story":["罗斯福与丘吉尔在卡萨布兰卡讨论战争方向，提出要求轴心国无条件投降。盟国需要说明如何结束战争，也仍在争论先攻意大利还是尽早跨海进入法国。","苏军打通通往列宁格勒的有限陆上走廊，改善围城居民与守军处境，但围困尚未完全解除。斯大林格勒包围圈继续缩小，德国大军的末日已近，平民与士兵的苦难却未因胜利接近而立即结束。"],"perspectives":[{"country":"uk","text":"主张地中海行动，需与美国对跨海进攻的期待协调。"},{"country":"su","text":"希望西方分担德军压力，同时继续以自身陆上攻势改变战局。"}],"sources":[{"id":"nz","locator":"1943-01对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"ww2dates","locator":"1943-01对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1943-02","date":"1943-02","title":"斯大林格勒投降，瓜岛日军撤离","theaters":["东线","太平洋","北非"],"countries":["su","de","us","jp"],"people":["保卢斯","崔可夫"],"story":["2日，斯大林格勒最后被围德军投降，保卢斯已成为苏军战俘。德国失去重要军队，纳粹宣传无法再维持此前的胜利叙事，苏德战局出现重大转折。","日本也完成瓜岛撤军，把持续消耗的局部战场交给对手。北非美军在卡塞林遭挫，说明盟国正在获得主动，却仍会失败并需学习；胜利的趋势不能抹平各部队实际经历的艰难。"],"perspectives":[{"country":"su","text":"城市防御与外围反攻结合取得成果，伤亡和重建代价极其巨大。"},{"country":"jp","text":"放弃难以补给的阵地，战略防御压力从此持续扩大。"}],"sources":[{"id":"ww2dates","locator":"1943-02对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1943-02对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":["battle-stalingrad"]},{"id":"ww2-1943-03","date":"1943-03","title":"哈尔科夫反击：转折之后仍有反复","theaters":["东线","亚洲"],"countries":["de","su","us","jp"],"people":["曼施坦因","史迪威"],"story":["德军反击夺回哈尔科夫，表明斯大林格勒之后德国仍保有强大战役能力。苏军推进过快、战线展开和补给问题提供了机会，战争转折并不意味着之后每一次交战都必然获胜。","缅甸等地盟军探索远程渗透和改善作战方法，运输与疾病依然制约行动。各战区都在积累经验，而下一轮大规模决战正在准备。"],"perspectives":[{"country":"de","text":"局部反击恢复一定态势，却无法重新获得1941年的总体条件。"},{"country":"su","text":"需要巩固防御与预备队，避免胜利后的过度延伸。"}],"sources":[{"id":"ww2dates","locator":"1943-03对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1943-03对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1943-04","date":"1943-04","title":"华沙隔都起义：被迫害者不是没有抵抗","theaters":["平民","东线"],"countries":["pl","de","su"],"people":["莫尔德哈伊·阿涅莱维奇"],"story":["19日，华沙隔都中的犹太抵抗者在德军准备进一步驱逐时起义。武器与补给极为有限，抵抗面对的是国家组织的屠杀机器，不能用正规军胜负标准衡量其意义。","纳粹镇压并毁坏隔都，幸存者仍面临被捕和杀害。同期卡廷屠杀墓地的发现引发波兰流亡政府与苏联关系危机，盟国内部对责任和未来安排的冲突也不能因共同抗德而略去。"],"perspectives":[{"country":"pl","text":"犹太居民的抵抗与波兰国家命运相互交织，但各群体经历并不相同。"},{"country":"su","text":"与波兰关系恶化影响战后政治安排，历史责任须以证据辨认。"}],"sources":[{"id":"ghetto","locator":"1943-04对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"katyn","locator":"1943-04对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1943-05","date":"1943-05","title":"突尼斯投降，大西洋运输形势改善","theaters":["北非","海战"],"countries":["uk","us","de","it"],"people":["艾森豪威尔","蒙哥马利"],"story":["轴心国在突尼斯的部队投降，北非战役主要阶段结束。盟军从东西两个方向压缩对手，海空力量与补给优势终于使轴心国难以继续维持立足点。","大西洋反潜在护航、航空、雷达与情报协作下取得明显进展，德国潜艇损失加重。安全抵达的货物与部队，为后来登陆欧洲提供条件，海战的成果正在转化为大陆作战能力。"],"perspectives":[{"country":"us","text":"北非实战与跨国指挥经验，为更大规模行动铺路。"},{"country":"de","text":"潜艇无法切断盟国海运，长期资源竞争更加不利。"}],"sources":[{"id":"nz","locator":"1943-05对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"sea","locator":"1943-05对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1943-06","date":"1943-06","title":"库尔斯克之前：等待也是战争的一部分","theaters":["东线","后方"],"countries":["su","de","us","uk"],"people":["朱可夫","希特勒"],"story":["德军准备攻击库尔斯克突出部，苏军修筑纵深防御、布雷并集结预备队。情报与准备使防守不再只是被动等待，工业恢复和兵力组织开始改变下一次决战的条件。","西方盟军筹备西西里登陆，争论和计划必须落实为船只、训练、港口与航空保障。一个月没有新的决定性会战，也不等于战争停顿，未来战果常由这些不显眼的准备决定。"],"perspectives":[{"country":"su","text":"准备承受进攻后转入反击，依靠纵深和预备力量。"},{"country":"de","text":"推迟进攻有利于装备补充，也给对手更多筑垒时间。"}],"sources":[{"id":"ww2dates","locator":"1943-06对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1943-06对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1943-07","date":"1943-07","title":"库尔斯克、西西里与墨索里尼倒台","theaters":["东线","欧洲"],"countries":["su","de","uk","us","it"],"people":["朱可夫","希特勒","墨索里尼"],"story":["5日，德军进攻库尔斯克，苏军在纵深防御中阻击并转入反攻。装甲战只是整个会战的一部分，炮兵、步兵、工事与预备队同样重要，不能以一场坦克遭遇概括全部。","盟军登陆西西里，意大利统治集团的危机加剧。25日，墨索里尼被解除职务并遭逮捕，法西斯政权失去原有支撑，但德国不会因此放弃控制意大利。","军事失利如何传导到政治更替，在这一月格外清楚。更换领导人并没有立即带来全国和平，意大利即将面对占领、内战式冲突和长期前线。"],"perspectives":[{"country":"it","text":"战争失败促成政权危机，退出轴心国的道路仍有巨大风险。"},{"country":"su","text":"在阻击后扩大反攻，德军越来越难恢复东线战略主动。"}],"sources":[{"id":"ww2dates","locator":"1943-07对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1943-07对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1943-08","date":"1943-08","title":"西西里战役结束，意大利秘密谈判","theaters":["欧洲","东线"],"countries":["it","de","uk","us","su"],"people":["巴多格里奥","艾森豪威尔"],"story":["盟军完成对西西里的主要占领，轴心国部分部队撤回意大利本土。守军撤离保存了继续防御的力量，因此占岛胜利并不意味着下一阶段登陆会轻易完成。","意大利政府与盟军秘密接触，德国则加强防备。苏军收复哈尔科夫并继续向西推进，两个方向共同挤压轴心国，联盟合作与各国自救也在同时改变政治关系。"],"perspectives":[{"country":"it","text":"试图退出战争，却必须面对德国军队和本国部队安全问题。"},{"country":"de","text":"准备在盟友倒向对手时直接接管关键地区。"}],"sources":[{"id":"ww2dates","locator":"1943-08对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1943-08对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1943-09","date":"1943-09","title":"意大利停战，却没有停止战斗","theaters":["欧洲","东线"],"countries":["it","de","us","uk","su"],"people":["巴多格里奥","墨索里尼"],"story":["意大利与盟军停战安排公布，盟军在萨莱诺等地登陆。德国迅速解除大量意军武装并占领关键地区，获救的墨索里尼在北方建立依附德国的政权，意大利国土成为长期战场。","苏军向第聂伯河推进，需要在宽阔河流与德军防御前建立桥头堡。地图上连续后退的箭头，背后仍是极为困难的渡河、运输与近距离作战。"],"perspectives":[{"country":"it","text":"退出原有联盟并不等于军民脱离战争，许多士兵成为被俘或遭杀害者。"},{"country":"su","text":"追击成果需要通过工程、补给和步兵作战才能维持。"}],"sources":[{"id":"ww2dates","locator":"1943-09对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1943-09对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1943-10","date":"1943-10","title":"意大利对德宣战，殖民地饥荒持续","theaters":["欧洲","后方"],"countries":["it","uk","de"],"people":["巴多格里奥"],"story":["意大利政府对德宣战，部分力量转而与盟军合作，北方抵抗运动也逐步发展。政权、军队与居民的选择分裂，不能再用一个国旗概括所有人的政治立场。","孟加拉饥荒在战争环境下造成灾难，粮食供应、运输、价格与殖民治理的失误相互作用。对英国战争史的阅读，不能只停在伦敦防空与北非胜利，也应看到帝国臣民承受的严重苦难。"],"perspectives":[{"country":"it","text":"共同交战与被占领处境并存，国家重建的政治问题逐渐出现。"},{"country":"uk","text":"战争资源调配与殖民治理对平民生存负有责任，相关解释须结合多方面研究。"}],"sources":[{"id":"nz","locator":"1943-10对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"bengal","locator":"1943-10对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1943-11","date":"1943-11","title":"开罗与德黑兰：盟国开始谈论战后","theaters":["外交","中国","东线"],"countries":["cn","us","uk","su","de","jp"],"people":["蒋介石","罗斯福","丘吉尔","斯大林"],"story":["中美英领导人在开罗会晤，讨论对日战争与战后安排，相关宣言于12月1日发表。随后美英苏在德黑兰商讨跨海进攻法国等问题，盟国对战场分工逐渐形成更明确安排。","苏军收复基辅，中国常德会战也在进行。外交桌上的方案仍依赖前线流血与运输资源才能兑现，各国参与程度与核心利益不同，多国合作并不意味着没有分歧。"],"perspectives":[{"country":"cn","text":"通过开罗会议参与亚洲战后安排，同时仍在本土承受日军攻势。"},{"country":"su","text":"要求西方开辟法国战线，并讨论东欧等战后安全问题。"}],"sources":[{"id":"cairo","locator":"1943-11对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"tehran","locator":"1943-11对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"china","locator":"1943-11对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1943-12","date":"1943-12","title":"宣言发表，意大利山地仍难越过","theaters":["外交","欧洲","中国"],"countries":["cn","jp","us","uk","de"],"people":["蒋介石","罗斯福","丘吉尔"],"story":["开罗宣言发表，提出日本归还从中国窃取的领土等战后目标。宣言确立政治方向，但实现它仍取决于继续对日作战与后来受降、接收等安排。","常德会战结束后中国继续作战，意大利前线则陷入冬季山地与河流防御。盟军虽然总体占优，仍要面对一次次局部僵持，战争结束的政治设想与前线实际距离尚远。"],"perspectives":[{"country":"cn","text":"战后主权诉求获得重要表达，抗战本身仍未结束。"},{"country":"uk","text":"同时筹备法国登陆和意大利推进，资源优先次序需要不断调整。"}],"sources":[{"id":"cairo","locator":"1943-12对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"china","locator":"1943-12对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1943-12对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1944-01","date":"1944-01","title":"列宁格勒解围，安齐奥登陆","theaters":["东线","欧洲"],"countries":["su","de","uk","us"],"people":["朱可夫","艾森豪威尔"],"story":["苏军攻势彻底解除列宁格勒长期围困，城市与居民遭受的损失却无法简单用一场胜利弥补。幸存者面临医疗、营养与重建，胜利之后的人道任务立即开始。","盟军在安齐奥登陆，希望从侧后突破意大利防线，却很快受到德军围堵。越过第一道海岸并不等于切断敌军退路，登陆成功与战役突破仍是两个不同阶段。"],"perspectives":[{"country":"su","text":"围城结束具有重大象征与实际意义，城市创伤延续更久。"},{"country":"us","text":"必须把滩头补给和指挥判断转化为纵深行动，不能只计算登陆兵力。"}],"sources":[{"id":"nz","locator":"1944-01对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"ww2dates","locator":"1944-01对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1944-02","date":"1944-02","title":"卡西诺修道院被炸，残垣仍成战场","theaters":["欧洲","太平洋"],"countries":["uk","us","de","jp"],"people":["弗赖伯格","尼米兹"],"story":["盟军轰炸卡西诺修道院，试图解除对防线的威胁，却造成文化遗产毁坏和人员伤亡。废墟随后仍便于防御，军事判断与预期后果之间出现令人警醒的反差。","太平洋美军在马绍尔群岛推进并袭击特鲁克基地，逐步削弱日本外围体系。选择绕过哪些据点、夺取哪些机场，需要结合运输和后续行动，而不是一岛不漏地正面攻占。"],"perspectives":[{"country":"uk","text":"多国部队参与意大利作战，受限地形使火力优势难以直接转为突破。"},{"country":"jp","text":"基地遭袭与海上交通损失，削弱整个防御圈的相互支援。"}],"sources":[{"id":"nz","locator":"1944-02对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pacific","locator":"1944-02对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1944-03","date":"1944-03","title":"日军进攻印度方向，补给成为赌注","theaters":["亚洲","欧洲"],"countries":["jp","uk","cn","de"],"people":["牟田口廉也","威廉·斯利姆"],"story":["日军从缅甸向英帕尔、科希马方向进攻，希望打乱盟军基地和交通。越过山地后，日军必须依靠极困难的运输维持作战，夺取敌方物资的期待难以替代可靠补给。","卡西诺继续激战，德国又占领匈牙利，进一步扩大对当地犹太人的迫害与驱逐。军事战线的变化与种族灭绝的推进同时发生，不能把欧洲战争只读成盟军逐步前进的地图。"],"perspectives":[{"country":"jp","text":"冒险进攻依赖薄弱后勤，把兵员暴露于饥饿和疾病。"},{"country":"uk","text":"利用空运、坚守与增援消耗对手，缅印战局逐步改变。"}],"sources":[{"id":"nz","locator":"1944-03对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"holocaust","locator":"1944-03对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":["imphal-kohima"]},{"id":"ww2-1944-04","date":"1944-04","title":"一号作战：世界转折没有让中国战场轻松","theaters":["中国","亚洲"],"countries":["cn","jp","uk"],"people":["蒋介石","威廉·斯利姆"],"story":["日本在中国发动一号作战，企图打通大陆交通并摧毁相关航空基地，攻势从河南扩向湖南、广西。中国军队在多处遭受严重失败，大片地区及民众面临占领和迁徙。","与此同时，英帕尔、科希马地区盟军仍与日军激战。日本在不同战区继续投入攻势，说明总体战略劣势并未使其立即丧失进攻能力，中国承受的战争压力也没有因欧洲盟军准备登陆而消失。"],"perspectives":[{"country":"cn","text":"需要面对军队组织、补给与治理问题造成的危机，也仍保持长期抵抗。"},{"country":"jp","text":"用大规模陆上进攻争取交通和基地，代价是更长战线与更深消耗。"}],"sources":[{"id":"china","locator":"1944-04对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1944-04对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1944-05","date":"1944-05","title":"卡西诺突破与滇西反攻","theaters":["欧洲","中国","亚洲"],"countries":["uk","us","de","cn","jp"],"people":["亚历山大","史迪威"],"story":["盟军在卡西诺及意大利防线上取得突破，安齐奥部队也向外推进。长期准备、多国部队协同和对地形的适应，终于使此前停滞的战线开始移动。","中国军队在滇西等地反攻，试图恢复对外交通，与驻印部队在缅北的作战相互联系。打通一条道路意味着夺取高地、渡过河流并重建运输设施，其代价不能用一个“会师”词语概括。"],"perspectives":[{"country":"cn","text":"在本土承受日军攻势的同时，仍需为外援通道投入力量。"},{"country":"uk","text":"意大利突破改善局势，法国登陆准备仍占据更高战略优先级。"}],"sources":[{"id":"nz","locator":"1944-05对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"china","locator":"1944-05对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1944-06","date":"1944-06","title":"诺曼底与巴格拉季昂：两面压力终于汇合","theaters":["西线","东线","太平洋"],"countries":["us","uk","fr","su","de","jp"],"people":["艾森豪威尔","蒙哥马利","朱可夫","罗科索夫斯基"],"story":["6日，盟军在诺曼底登陆，空降与海上部队争夺滩头、道路和桥梁。成功建立登陆场只是起点，瑟堡、卡昂与法国乡间的攻防还将持续数周。","22日，苏军发动巴格拉季昂行动，重创德国中央集团军群。东西两线的连续压力迫使德国更加难以集中预备队，不能只以登陆日概括这一月对德战争的改变。","太平洋美军进攻塞班，菲律宾海海战重创日本海军航空兵。不同战区的行动使轴心国日益失去恢复力量的时间，胜利仍伴随军民重大伤亡。"],"perspectives":[{"country":"su","text":"以大规模陆上进攻牵制并摧毁德军，不是等待西线代替自己完成战争。"},{"country":"us","text":"同时承担欧洲登陆和太平洋推进，工业与海运能力成为协同基础。"}],"sources":[{"id":"ww2dates","locator":"1944-06对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1944-06对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pacific","locator":"1944-06对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":["battle-normandy"]},{"id":"ww2-1944-07","date":"1944-07","title":"突破法国防线，德国政变失败","theaters":["西线","东线","后方"],"countries":["us","uk","fr","de","su","jp"],"people":["艾森豪威尔","希特勒","施陶芬贝格"],"story":["盟军在诺曼底持续作战后，通过眼镜蛇行动等突破进入法国纵深；苏军也向波兰方向推进。德国同时在多处后撤，前线失利加剧统治内部危机。","20日，施陶芬贝格等人的刺杀希特勒与政变失败，纳粹随后严厉清洗。日本塞班失守，东条内阁倒台，军事挫折在不同轴心国都传入政治核心，却未立即结束这些政权继续战争的决定。"],"perspectives":[{"country":"de","text":"部分精英反抗并未成功，纳粹镇压使继续战争的体制仍维持。"},{"country":"jp","text":"丧失重要防御位置后更换内阁，却仍未接受投降。"}],"sources":[{"id":"ww2dates","locator":"1944-07对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1944-07对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1944-08","date":"1944-08","title":"巴黎解放，华沙却在孤立中燃烧","theaters":["西线","东线"],"countries":["fr","pl","de","su","us","uk"],"people":["戴高乐","艾森豪威尔"],"story":["巴黎起义后，自由法国和盟军进入城市，首都解放成为恢复法国政治地位的重要时刻。法国抵抗、盟军推进与国家重建相互联系，胜利既是军事成果，也是政治合法性的重塑。","华沙国内军起义却未获足够外援，德军残酷镇压，苏军停在维斯瓦河另一侧的局面引发长期争议。罗马尼亚又发生政变并退出原轴心立场，同一月的解放、失败与转向呈现战争末期不同命运。"],"perspectives":[{"country":"fr","text":"争取以本国力量参与解放，有助恢复战后独立政治地位。"},{"country":"pl","text":"对自主解放和国家前途的追求，陷入德军镇压与盟国战略政治关系的夹缝。"}],"sources":[{"id":"ww2dates","locator":"1944-08对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1944-08对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1944-09","date":"1944-09","title":"市场花园受挫，胜利仍受交通约束","theaters":["西线","东线"],"countries":["uk","us","de","su"],"people":["蒙哥马利"],"story":["盟军发动市场花园行动，试图通过空降夺桥并以地面部队快速推进。阿纳姆等地受阻，使跨越莱茵河的目标未能实现，远距离补给与狭窄交通轴线放大了风险。","芬兰与苏联停战，欧洲联盟结构继续变化。西方盟军推进接近德国边境后，也必须处理港口、铁路和燃料供应，战线越接近敌方本土，并不意味着后勤问题会自动减少。"],"perspectives":[{"country":"uk","text":"冒险跨越障碍失败，说明资源优势仍需可靠计划与情报支持。"},{"country":"de","text":"局部防御仍可取得成果，但难以改变总体两线压力。"}],"sources":[{"id":"ww2dates","locator":"1944-09对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1944-09对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1944-10","date":"1944-10","title":"莱特湾与华沙起义的结局","theaters":["太平洋","东线"],"countries":["us","jp","pl","de"],"people":["麦克阿瑟","尼米兹"],"story":["美军登陆莱特，莱特湾海战使日本联合舰队遭受重大损失，难以再以原有方式组织大规模舰队决战。日本逐渐扩大特攻等手段，战争把人的生命更直接当作一次性武器。","华沙起义投降，城市和居民遭到进一步破坏。法国解放的喜悦无法代表所有被占领社会，战争末期仍有大量人在接近胜利时失去家园和生命。"],"perspectives":[{"country":"us","text":"重返菲律宾具有战略与政治意义，后续地面战争仍将造成深重损失。"},{"country":"jp","text":"海军力量衰退后转向更绝望的手段，不能将其浪漫化为纯粹勇武。"}],"sources":[{"id":"ww2dates","locator":"1944-10对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pacific","locator":"1944-10对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1944-11","date":"1944-11","title":"斯海尔德航道打开，东京进入轰炸范围","theaters":["西线","太平洋"],"countries":["uk","us","de","jp","cn"],"people":["艾森豪威尔"],"story":["盟军清理斯海尔德河口后，安特卫普港得以更有效投入补给，支持西线持续作战。夺取港口城市与真正使用港口不是一回事，航道、障碍和运输体系必须一并解决。","美军从马里亚纳群岛出动B-29攻击日本本土，远程空战进一步扩大。中国一号作战仍在向南推进，世界范围的盟国优势与某些地方居民继续遭受占领的现实并存。"],"perspectives":[{"country":"us","text":"基地与运输工程使远程轰炸成为持续行动，而非孤立突袭。"},{"country":"cn","text":"日军继续推进造成失土与迁徙，战争胜负趋势不能掩盖中国的即时苦难。"}],"sources":[{"id":"nz","locator":"1944-11对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pacific","locator":"1944-11对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"china","locator":"1944-11对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1944-12","date":"1944-12","title":"阿登反攻：最后的豪赌","theaters":["西线","东线"],"countries":["de","us","uk","su"],"people":["希特勒","艾森豪威尔","巴顿"],"story":["16日，德军在阿登发动反攻，试图分割盟军并改变西线局面。初期突然性造成危机，巴斯托涅等地坚守与盟军调动逐渐遏制进攻，天气改善后盟军航空兵作用增强。","德国难以补充燃油和损失，最后的大规模西线攻势最终消耗了更多防御资源。苏军围攻布达佩斯，欧洲战争继续逼近轴心国核心，年末的反击延长苦难，却未能改变资源与力量的总体对比。"],"perspectives":[{"country":"de","text":"政治愿望驱动高风险攻势，把有限预备队再次投入难以持续的作战。"},{"country":"us","text":"危机考验机动、补给和指挥协调，最终依靠整体资源恢复主动。"}],"sources":[{"id":"ww2dates","locator":"1944-12对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1944-12对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1945-01","date":"1945-01","title":"维斯瓦—奥得攻势与奥斯维辛解放","theaters":["东线","平民"],"countries":["su","de","pl","us","uk"],"people":["朱可夫","科涅夫"],"story":["苏军从维斯瓦河方向大举推进，迅速逼近德国核心地区。纳粹在撤退中驱赶集中营囚犯进行死亡行军，许多人在严寒、饥饿和杀戮中死亡，解放到来前的最后阶段仍极其致命。","27日，苏军进入奥斯维辛，发现幸存者与大规模犯罪遗迹。战争结束不能让死者复生，保存档案、证言和物证成为随后追究责任与抵抗否认的重要基础。"],"perspectives":[{"country":"su","text":"军事推进与接触大屠杀遗址同时发生，救护和记录成为新任务。"},{"country":"pl","text":"国土上的灭绝营与长期占领留下深重创伤，国家前途仍受战后政治影响。"}],"sources":[{"id":"holocaust","locator":"1945-01对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"ww2dates","locator":"1945-01对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1945-02","date":"1945-02","title":"雅尔塔、硫黄岛与德累斯顿","theaters":["外交","太平洋","平民"],"countries":["us","uk","su","de","jp"],"people":["罗斯福","丘吉尔","斯大林"],"story":["美英苏领导人在雅尔塔讨论德国占领、联合国和欧洲战后安排，并商谈苏联对日参战。合作仍围绕击败共同敌人，波兰等地政治问题却已显示潜在冲突，亚洲相关秘密安排也影响其他国家利益。","美军登陆硫黄岛，德累斯顿遭盟军猛烈空袭。会议桌上的秩序规划与前线、城市中的死亡同时存在，讨论战略必要性不能省略平民伤亡与决策争议。"],"perspectives":[{"country":"su","text":"寻求战后安全和影响范围，相关要求与其他国家主权诉求存在冲突。"},{"country":"us","text":"准备结束欧洲战争并对日作战，同时面对不同武力手段的伦理问题。"}],"sources":[{"id":"yalta","locator":"1945-02对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1945-02对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1945-03","date":"1945-03","title":"越过莱茵河，东京遭大规模燃烧弹轰炸","theaters":["西线","太平洋"],"countries":["us","uk","de","jp"],"people":["艾森豪威尔","李梅"],"story":["盟军在雷马根等处跨越莱茵河，德国西部防御进一步瓦解。渡河之后仍需占领地区、接收俘虏并维持补给，推进速度与组织能力密切相关。","东京在大规模燃烧弹空袭中遭到严重毁坏，大量平民死亡。对日本工业和战争能力的打击，与密集木结构居民区承受的灾难同时发生，空袭史不能只按投弹吨数和摧毁面积书写。"],"perspectives":[{"country":"us","text":"空中力量取得压倒性优势，也承担攻击人口密集城市的决策责任。"},{"country":"jp","text":"普通居民面对火灾与失所，政府仍未停止战争。"}],"sources":[{"id":"ww2dates","locator":"1945-03对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1945-03对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"pacific","locator":"1945-03对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1945-04","date":"1945-04","title":"柏林陷落前，领导人更替与联合国筹建","theaters":["东线","西线","外交","亚洲"],"countries":["su","de","us","uk","cn","jp"],"people":["朱可夫","罗斯福","杜鲁门","希特勒"],"story":["苏军发动柏林攻势，德军在城市周围与内部继续抵抗，30日希特勒自杀。美苏部队在易北河会合，德国被军事分割，纳粹统治的终结已经临近。","罗斯福去世，杜鲁门接任美国总统；旧金山会议开幕，筹建联合国。亚洲冲绳登陆与中国湘西等地战斗仍在继续，欧洲胜利在望并不意味着世界各地已能停止付出生命。"],"perspectives":[{"country":"us","text":"新总统接手核计划、对日战争和战后外交等重大决策。"},{"country":"cn","text":"参与新国际组织筹建，同时仍需在本土和亚洲战场继续抵抗日本。"}],"sources":[{"id":"ww2dates","locator":"1945-04对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1945-04对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"un","locator":"1945-04对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1945-05","date":"1945-05","title":"德国投降，战争尚未在亚洲结束","theaters":["欧洲","亚洲"],"countries":["de","su","uk","us","cn","jp"],"people":["邓尼茨","艾森豪威尔"],"story":["德国在兰斯与柏林先后签署投降文件，欧洲中部时间8日深夜生效，莫斯科已经进入9日，因此不同国家纪念日有差异。柏林守军此前已投降，欧洲战争主要阶段结束。","盟军面对幸存者、流亡人口、战俘和被毁城市，解放与救援立即转为重建任务。缅甸仰光被收复，亚洲战事仍在进行，欧洲的庆祝必须与尚未结束的对日战争并列阅读。"],"perspectives":[{"country":"de","text":"纳粹统治结束后，去纳粹化、责任追究与社会重建成为艰难任务。"},{"country":"cn","text":"对德胜利改善总体局势，但中国军民仍未等到抗战结束。"}],"sources":[{"id":"ww2dates","locator":"1945-05对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"nz","locator":"1945-05对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1945-06","date":"1945-06","title":"冲绳战役结束，联合国宪章签署","theaters":["太平洋","外交"],"countries":["us","jp","cn","uk","su"],"people":["杜鲁门"],"story":["冲绳主要战斗结束，美军、日军与当地平民都付出巨大代价，居民遭战争和日军控制逼入绝境的经历必须保留。盟军继续讨论如何迫使日本投降，登陆本土的成本只是其中一个考虑。","26日，联合国宪章在旧金山签署，集体安全、人权与国际合作被写入新的制度框架。制度由战争灾难催生，却仍需国家行为支持，不能把签字等同于今后自然不会再发生战争。"],"perspectives":[{"country":"jp","text":"本土附近战败与平民灾难未能立即改变政府决策。"},{"country":"cn","text":"作为创始参与国之一进入新国际制度，也期待主权与战后恢复。"}],"sources":[{"id":"nz","locator":"1945-06对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"un","locator":"1945-06对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1945-07","date":"1945-07","title":"波茨坦与核试验：结束战争的选择","theaters":["外交","后方"],"countries":["us","uk","su","cn","jp"],"people":["杜鲁门","斯大林","丘吉尔","艾德礼"],"story":["16日，美国进行首次核爆炸试验；随后波茨坦会议讨论德国与战后安排，英国大选又使艾德礼接替丘吉尔参加会议。共同敌人消失后，盟国在欧洲利益上的分歧更加明显。","26日，中美英发表波茨坦公告，要求日本投降，苏联当时尚未对日宣战，没有作为最初署名国。日本领导层继续寻求不愿放弃的条件，原子弹、苏联行动与军事封锁正共同逼近最终抉择。"],"perspectives":[{"country":"us","text":"拥有新武器并不消除使用它的伦理与外交责任。"},{"country":"jp","text":"仍试图保留条件、寻求调停，低估继续拖延给军民带来的风险。"}],"sources":[{"id":"potsdam","locator":"1945-07对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"atomic","locator":"1945-07对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1945-08","date":"1945-08","title":"广岛、苏联参战、长崎与日本接受投降","theaters":["太平洋","中国","外交","平民"],"countries":["us","jp","su","cn","uk"],"people":["杜鲁门","裕仁","斯大林"],"story":["6日美国在广岛投下原子弹，8日苏联对日宣战，9日起在中国东北等地展开攻势；同日美国又在长崎投下原子弹。核爆、对苏调停希望破灭、军事失败与封锁等因素集中冲击日本决策。","日本领导层经过争执与天皇介入决定接受波茨坦公告，15日通过广播向民众宣布。日本全国与各地驻军停止行动、缴械和受降仍需时间，中国等地也要组织接收、救援与恢复秩序。","关于原子弹、苏联参战及其他因素各占多大作用，史学界有持续讨论，不能用单一原因抹去复杂过程。无论怎样评估决策，广岛、长崎及其他地区平民承受的死亡、辐射伤害和长期创伤都不应被抽象战果取代。"],"perspectives":[{"country":"jp","text":"政府终于接受失败，居民既是战争动员对象，也承受国家坚持侵略的后果。"},{"country":"cn","text":"长期抵抗走向胜利，收复失地、处理战争遗产与重建仍将极其艰难。"}],"sources":[{"id":"surrender","locator":"1945-08对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"potsdam","locator":"1945-08对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"command","locator":"1945-08对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]},{"id":"ww2-1945-09","date":"1945-09","title":"东京湾签字：中国受降与漫长的战后","theaters":["外交","中国","后方"],"countries":["jp","us","cn","uk","su","fr"],"people":["麦克阿瑟","徐永昌","何应钦","重光葵"],"story":["2日，日本代表在东京湾密苏里号签署投降书，盟国代表接受，第二次世界大战在通常使用的全球分期中正式结束。中国代表徐永昌在场签字，9日南京又举行中国战区受降仪式。","受降不是所有苦难的终点。战俘与劳工返乡、被占领地区接收、战争罪行调查、失踪人员追寻和经济重建接踵而来，殖民体系与大国关系也进入新的动荡。","两次世界大战的比较，最终应回到人和制度：宣传怎样压过事实，国家如何组织暴力，普通人如何抵抗与救助，国际合作又为何会失效或被重新建立。胜利需要纪念，战争发生的条件与责任更需要持续辨认。"],"perspectives":[{"country":"cn","text":"胜利带来主权恢复与新国际地位，长期破坏和内部矛盾仍待解决。"},{"country":"jp","text":"解除武装、占领改革和责任追究开始，社会必须面对侵略历史。"}],"sources":[{"id":"surrender","locator":"1945-09对应日期／本条标题所述主题；背景解释为本站归纳"},{"id":"china","locator":"1945-09对应日期／本条标题所述主题；背景解释为本站归纳"}],"relatedBattles":[]}]}],"sources":[{"id":"nam14","title":"一战年度档案：1914","publisher":"英国国家陆军博物馆","url":"https://ww1.nam.ac.uk/theme/year-1914/","note":"年度主题索引；具体月份另与该馆总时间线交叉定位。"},{"id":"nam15","title":"一战年度档案：1915","publisher":"英国国家陆军博物馆","url":"https://ww1.nam.ac.uk/theme/year-1915/","note":"年度主题索引；具体月份另与该馆总时间线交叉定位。"},{"id":"nam16","title":"一战年度档案：1916","publisher":"英国国家陆军博物馆","url":"https://ww1.nam.ac.uk/theme/year-1916/","note":"年度主题索引；具体月份另与该馆总时间线交叉定位。"},{"id":"nam17","title":"一战年度档案：1917","publisher":"英国国家陆军博物馆","url":"https://ww1.nam.ac.uk/theme/year-1917/","note":"年度主题索引；具体月份另与该馆总时间线交叉定位。"},{"id":"nam18","title":"一战年度档案：1918","publisher":"英国国家陆军博物馆","url":"https://ww1.nam.ac.uk/theme/year-1918/","note":"年度主题索引；具体月份另与该馆总时间线交叉定位。"},{"id":"namtime","title":"第一次世界大战时间线","publisher":"英国国家陆军博物馆","url":"https://ww1.nam.ac.uk/timeline/","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"armenian","title":"亚美尼亚种族灭绝：概述","publisher":"美国大屠杀纪念馆","url":"https://encyclopedia.ushmm.org/content/en/article/the-armenian-genocide-1915-16-overview","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"usentry","title":"美国参加第一次世界大战","publisher":"美国国务院历史办公室","url":"https://history.state.gov/milestones/1914-1920/wwi","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"verdun","title":"一战整体与凡尔登战场背景","publisher":"英国国家陆军博物馆","url":"https://www.nam.ac.uk/explore/first-world-war","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"somme","title":"索姆河战役","publisher":"英国国家陆军博物馆","url":"https://www.nam.ac.uk/explore/battle-somme","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"chinaWW1","title":"十四点原则与中国山东问题","publisher":"美国国家一战博物馆","url":"https://www.theworldwar.org/learn/peace/fourteen-points","note":"结合一战年度时间线与中国参战、华工条目阅读。"},{"id":"fourteen","title":"威尔逊十四点原则","publisher":"美国国务院历史办公室","url":"https://history.state.gov/milestones/1914-1920/fourteen-points","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"peace","title":"巴黎和会与凡尔赛条约","publisher":"美国国务院历史办公室","url":"https://history.state.gov/milestones/1914-1920/paris-peace","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"china","title":"抗战大事记","publisher":"人民日报资料／中央纪委网站刊载","url":"https://m.ccdi.gov.cn/content/3e/04/4363.html","note":"以文中相应年月定位，并与本站既有抗战战役、党史资料交叉阅读；不照搬个别战果口径。"},{"id":"mao38","title":"中国共产党一百年大事记","publisher":"中共中央党史和文献研究院","url":"https://www.12371.cn/2021/06/28/ARTI1624828749818652.shtml","note":"定位1938年《论持久战》；亦参照本站既有1938年党史资料。"},{"id":"pearl","title":"中国、日本、美国与通向珍珠港之路","publisher":"美国国务院历史办公室","url":"https://history.state.gov/milestones/1937-1945/pearl-harbor","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"holocaust","title":"纳粹迫害与大屠杀时间线","publisher":"美国大屠杀纪念馆","url":"https://encyclopedia.ushmm.org/content/en/timeline/holocaust","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"prewar","title":"第二次世界大战关键日期：前史及战争","publisher":"美国大屠杀纪念馆","url":"https://encyclopedia.ushmm.org/content/en/article/world-war-ii-key-dates","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"nanjing","title":"南京大屠杀案罪行调查表","publisher":"国家档案局／南京市档案馆","url":"https://www.saac.gov.cn/zt/2014-12/11/content_77660.htm","note":"1946年调查材料的档案展陈；个别证言是具体个案，不据此推算整体人数。"},{"id":"ww2dates","title":"第二次世界大战关键日期","publisher":"美国大屠杀纪念馆","url":"https://encyclopedia.ushmm.org/content/en/article/world-war-ii-key-dates","note":"用于日期交叉核对；个别事件起讫口径与其他编年资料有差别，不把简表视为完整战史。"},{"id":"neutral","title":"美国1930年代中立法","publisher":"美国国务院历史办公室","url":"https://history.state.gov/milestones/1921-1936/neutrality-acts","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"winter","title":"冬季战争80周年史事说明","publisher":"芬兰总理办公室","url":"https://valtioneuvosto.fi/en/-/winter-war-began-80-years-ago-today","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"sea","title":"大西洋战役概述","publisher":"美国海军历史与遗产司令部","url":"https://www.history.navy.mil/content/history/nhhc/browse-by-topic/wars-conflicts-and-operations/world-war-ii/1942/atlantic/overview.html","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"home","title":"二战美国后方编年选录","publisher":"美国国家二战博物馆","url":"https://www.nationalww2museum.org/home-front-selected-chronology","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"lend","title":"租借法与盟国援助","publisher":"美国国务院历史办公室存档","url":"https://2001-2009.state.gov/r/pa/ho/time/wwii/81508.htm","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"yugoslavia","title":"轴心国入侵南斯拉夫","publisher":"美国大屠杀纪念馆","url":"https://encyclopedia.ushmm.org/content/en/article/axis-invasion-of-yugoslavia","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"nz","title":"第二次世界大战逐年时间线","publisher":"新西兰文化与遗产部 NZ History","url":"https://nzhistory.govt.nz/war/second-world-war/timeline","note":"按日期主题定位；时间线存在个别错误或口径差异，须与专题档案及其他官方编年交叉核对。"},{"id":"pacific","title":"二战整体与太平洋战场导读","publisher":"英国国家陆军博物馆","url":"https://www.nam.ac.uk/explore/second-world-war","note":"用于战场进程，不把概述中的简化日期替代具体事件起讫。"},{"id":"dunkirk","title":"敦刻尔克史实说明","publisher":"帝国战争博物馆","url":"https://www.iwm.org.uk/sites/default/files/press-release/dunkirk_film_2017_fact_sheet_and_iwm_resources_available.pdf","note":"不同资料对末批撤运日有口径差异，本文按跨5—6月叙述，未照搬单一截止日。"},{"id":"atlantic","title":"大西洋会议与宪章","publisher":"美国国务院历史办公室","url":"https://history.state.gov/milestones/1937-1945/atlantic-conf","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"wannsee","title":"万湖会议与会议记录","publisher":"万湖会议纪念教育馆","url":"https://www.ghwk.de/de/konferenz","note":"会议协调既在进行的种族灭绝，不是把屠杀起点简单定在会议当天。"},{"id":"atomic","title":"曼哈顿计划","publisher":"美国国家二战博物馆","url":"https://www.nationalww2museum.org/war/topics/manhattan-project","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"ghetto","title":"华沙隔都起义","publisher":"美国大屠杀纪念馆","url":"https://encyclopedia.ushmm.org/content/en/article/warsaw-ghetto-uprising","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"katyn","title":"卡廷罪行史料专题说明","publisher":"德国联邦独裁历史研究基金会","url":"https://www.bundesstiftung-aufarbeitung.de/de/stiftung/aktuelles/neues-online-dossier-zum-verbrechen-von-katyn","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"bengal","title":"Hungry Bengal: War, Famine and the End of Empire","publisher":"Janam Mukherjee／牛津大学出版社","url":"https://academic.oup.com/book/2861","note":"史学专著摘要；饥荒因果涉及供应、价格、殖民政策与战争，多种研究有不同解释，本文不写未核定死亡总数。"},{"id":"cairo","title":"开罗与德黑兰会议外交文件集","publisher":"美国国务院历史办公室 FRUS","url":"https://history.state.gov/historicaldocuments/frus1943CairoTehran","note":"定位1943年12月1日开罗公报及相关会议文件。"},{"id":"tehran","title":"德黑兰会议","publisher":"美国国务院历史办公室","url":"https://history.state.gov/milestones/1937-1945/tehran-conf","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"yalta","title":"雅尔塔会议","publisher":"美国国务院历史办公室","url":"https://history.state.gov/milestones/1937-1945/yalta-conf","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"un","title":"联合国宪章","publisher":"联合国","url":"https://www.un.org/en/about-us/un-charter","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"potsdam","title":"波茨坦会议","publisher":"美国国务院历史办公室","url":"https://history.state.gov/milestones/1937-1945/potsdam-conf","note":"编年事实与主题交叉核对；本站正文为原创叙述。"},{"id":"command","title":"Command Decisions：日本投降决策讨论","publisher":"美国陆军军事史中心","url":"https://history.army.mil/portals/143/Images/Publications/catalog/70-7.pdf","note":"书末关于日本投降因素的讨论；不同研究意见并列，不能以单因解释。部分网络环境可能无法打开军史网站。"},{"id":"surrender","title":"日本投降书：原件与释文","publisher":"美国国家档案馆","url":"https://www.archives.gov/milestone-documents/surrender-of-japan","note":"编年事实与主题交叉核对；本站正文为原创叙述。"}],"countries":[{"id":"de","name":"德国","views":{"ww1":"一战中的德国试图以快速击败法国解除两线压力，未能速胜后越来越依赖消耗、潜艇与强化动员。封锁、粮食短缺和军队损耗最终与革命相连，不能把失败归咎于所谓后方背叛。","ww2":"纳粹德国通过独裁、扩军和对外侵略追求支配欧洲，战争与种族灭绝、强迫劳动和资源掠夺相互连接。理解其战略计算，不意味着接受其宣传，更不能把纳粹政府、所有德国居民与抵抗者混为一个声音。"}},{"id":"uk","name":"英国及帝国","views":{"ww1":"英国从维护比利时中立与欧洲均势走入大战，依靠海军、金融和帝国资源支持西线。印度、非洲、加拿大、澳新等地部队和劳工的贡献，以及殖民统治的不平等，同样是这一视角的组成部分。","ww2":"法国失守后，英国守住本土并维持海运，逐步依靠美苏等盟国合作转入反攻。防空与社会动员值得研究，殖民地饥荒、种族等级和帝国利益也不可被胜利叙事遮蔽。"}},{"id":"fr","name":"法国","views":{"ww1":"本土遭到入侵，使收复领土与阻止德国再攻成为核心诉求。凡尔登、索姆河和1917年军队危机显示，士兵不是无穷资源，继续抵抗需要指挥、待遇与政治信任共同支撑。","ww2":"1940年失败带来占领与维希合作政权，也出现自由法国和地下抵抗。法国不是从战争中消失，而是在不同政治选择中持续存在，解放又与重建国家合法性联系起来。"}},{"id":"ru","name":"俄国／苏维埃俄国","views":{"ww1":"俄国为维护巴尔干影响与盟国关系参战，军事损失、运输困难和政治危机推动1917年两次革命。布尔什维克以严苛和约退出大战，仍未获得国内稳定和平。"}},{"id":"ah","name":"奥匈帝国","views":{"ww1":"帝国试图以打击塞尔维亚维护边疆统治，却在俄国、巴尔干和意大利战线长期消耗。依赖德国援助、粮食与民族政治危机逐步交织，最终帝国框架瓦解。"}},{"id":"rs","name":"塞尔维亚","views":{"ww1":"开战的直接压力来自奥匈，军民在抵抗、占领、撤退和流亡中承受重大损失。保存的军队此后继续作战，小国经历不能只当作大国外交的开场背景。"}},{"id":"ot","name":"奥斯曼帝国","views":{"ww1":"帝国加入同盟国后在海峡、高加索、两河与巴勒斯坦等地作战，加里波利防御与最终失败并存。亚美尼亚种族灭绝及对居民的暴力，是政权责任的核心问题，不能被军事成败掩盖。"}},{"id":"us","name":"美国","views":{"ww1":"美国先保持中立，金融贸易与潜艇冲突逐渐拉近其与协约国关系，1917年参战后需要时间形成远征能力。威尔逊推动和平原则，国内政治却阻止美国加入国际联盟。","ww2":"从有限援助转向正式参战，美国依靠工业、海运与联盟协调同时支撑欧洲和太平洋战场。反法西斯目标与国内种族不平等、日裔拘禁及城市轰炸的争议，需要一并审视。"}},{"id":"it","name":"意大利","views":{"ww1":"1915年转入协约国阵营，领土诉求使国家走进长期山地作战。卡波雷托失利与后来的防御重整，显示领导决策和士兵承受力的重要；战后不满也被法西斯政治利用。","ww2":"法西斯政权通过殖民侵略和对英法作战追求帝国地位，准备与资源却难支撑目标。1943年转向停战后，国土仍遭德国占领，并出现抵抗与合作政权并存的复杂局面。"}},{"id":"cn","name":"中国","views":{"ww1":"日本借对德战争占领青岛并扩大山东权益，中国的中立未能阻止战火。1917年参战和华工服务表达国际参与，巴黎和会的山东问题却显示弱国在胜方内部同样缺乏平等。","ww2":"中国从1931年局部抗战、1937年全面抗战走向1945年胜利。正面战场、敌后战场与社会动员长期牵制日本，合作抗日也伴随内部矛盾；失土、屠杀、轰炸、迁移与经济破坏构成军民的共同重负。"}},{"id":"jp","name":"日本","views":{"ww1":"日本对德作战并扩大东亚与太平洋权益，是协约国成员，但自身地区目标与其他盟国并不完全相同。山东问题将战时扩张延伸到战后争端。","ww2":"日本帝国通过侵华与南进夺取领土和资源，所谓解放亚洲的宣传与殖民占领、强迫劳动及暴行相矛盾。舰队失利、交通破坏和同盟压力最终迫使投降，平民受难不应被用来抹去侵略责任。"}},{"id":"su","name":"苏联","views":{"ww2":"苏联先与德国签订协定并参与东欧势力划分，1941年遭德国入侵后进行决定性的长期抵抗。工业转移、社会动员与军事学习支撑反攻；国家的伟大牺牲不抹去苏联自身的镇压与对他国主权的侵犯。"}},{"id":"pl","name":"波兰","views":{"ww2":"1939年遭德苏分割，占领不意味着国家与社会停止抵抗。犹太居民面对种族灭绝，地下军队与海外部队继续作战；1944年华沙起义与1945年后的政治安排，使解放和完全自主之间仍有距离。"}}],"people":[{"name":"威廉二世","life":"1859—1941","role":"德国皇帝","bio":"德国皇帝，参与帝国外交与战争决策。1914年支持奥匈，战争中军方权力逐渐上升；1918年退位并流亡。研究他可追踪君主声望、军国政治和统帅部权力如何共同影响国家选择。","wars":["ww1"]},{"name":"尼古拉二世","life":"1868—1918","role":"俄国皇帝","bio":"战争中亲任最高统帅，把王朝声望与军事成败直接相连。1917年退位，次年在俄国内战环境下被杀。其经历连接战场失利、后方供给与君主制崩溃。","wars":["ww1"]},{"name":"威尔逊","life":"1856—1924","role":"美国总统","bio":"带领美国从中立转向参战，提出十四点原则并推动国际联盟。巴黎和会中的妥协及美国国内批准失败，显示国际理想需要实际权力、联盟协调与国内政治支持。","wars":["ww1"]},{"name":"霞飞","life":"1852—1931","role":"法国将领","bio":"1914年在边境失利后重组部署，指挥体系下的马恩河反击遏止德军。后来长期攻势的损失引发争议，1916年离开主要指挥岗位，体现初期成功不能保证始终适应战争变化。","wars":["ww1"]},{"name":"贝当","life":"1856—1951","role":"法国将领；后任维希政权首脑","bio":"一战参与凡尔登防御，1917年处理法军军心危机；二战法国失败后领导维希政权并与纳粹德国合作，战后因叛国被判刑。人物评价必须区分阶段，不能以早年军功遮蔽后来责任。","wars":["ww1","ww2"]},{"name":"黑格","life":"1861—1928","role":"英国远征军统帅","bio":"主持索姆河、第三次伊普尔及1918年相关行动。其指挥涉及高昂伤亡、战略约束与军队学习，评价存在长期争论，既不能只以绰号否定，也不能仅以最终胜利消解代价。","wars":["ww1"]},{"name":"兴登堡","life":"1847—1934","role":"德国统帅；后任总统","bio":"一战由东线胜利获得声望，1916年与鲁登道夫掌握更大军事权力。后任德国总统并于1933年任命希特勒为总理，其政治生涯连接帝国战争与魏玛危机。","wars":["ww1"]},{"name":"鲁登道夫","life":"1865—1937","role":"德国军事领导人","bio":"与兴登堡共同强化战争统筹，支持冒险战略并组织1918年春季攻势。失败后参与极端民族主义政治，是理解统帅部责任及战败神话的重要人物。","wars":["ww1"]},{"name":"福煦","life":"1851—1929","role":"协约国统帅","bio":"1918年在危机中加强英法等军队统一协调，参与组织反攻与停战。其作用主要在联盟统筹，不能把盟军整体工业、兵员与各国部队贡献压缩为个人天才。","wars":["ww1"]},{"name":"克列孟梭","life":"1841—1929","role":"法国总理","bio":"1917年再度执政，推动继续作战与联盟协调，战后在巴黎和会强调法国安全。其政策反映法国被入侵经验，也与其他战胜国的均势和国际组织主张发生冲突。","wars":["ww1"]},{"name":"劳合·乔治","life":"1863—1945","role":"英国首相","bio":"1916年出任首相，重视军需与战争统筹，后来参与巴黎和会。在军事指挥、国家经济和帝国利益之间的权衡，是理解英国长期作战的重要切口。","wars":["ww1"]},{"name":"列宁","life":"1870—1924","role":"布尔什维克领导人","bio":"主张反对继续帝国主义战争，1917年革命后推动退出大战，接受布列斯特和约以保住新政权。退出国际战争与国内和平并不等同，俄国仍经历内战与政治暴力。","wars":["ww1"]},{"name":"穆斯塔法·凯末尔","life":"1881—1938","role":"奥斯曼将领；土耳其共和国创建者","bio":"参与加里波利防御，战后成为土耳其民族运动与建国的重要领导者。其一战角色与后来共和国政治应分阶段理解，不能把后来的国家身份直接套回1915年的帝国军队。","wars":["ww1"]},{"name":"希特勒","life":"1889—1945","role":"纳粹德国独裁者","bio":"通过独裁、种族主义与侵略扩张把德国带入世界战争，负有发动侵略与推动种族灭绝的核心责任。1945年在柏林自杀。叙述他的战略判断是为了辨认责任和机制，不能接受其自我辩解。","wars":["ww2"]},{"name":"墨索里尼","life":"1883—1945","role":"意大利法西斯独裁者","bio":"通过镇压与帝国扩张建立法西斯统治，侵略埃塞俄比亚并加入世界大战。1943年倒台后依靠德国在北方维持合作政权，1945年被意大利游击队处决。","wars":["ww2"]},{"name":"罗斯福","life":"1882—1945","role":"美国总统","bio":"推动租借援助、战争动员及同盟合作，参与战后国际组织规划。其政府同时实施日裔拘禁等侵犯权利政策。1945年4月去世，未亲历欧洲与对日战争最终胜利。","wars":["ww2"]},{"name":"丘吉尔","life":"1874—1965","role":"英国政治家、战时首相","bio":"一战参与推动达达尼尔行动，二战1940年出任首相，坚持对德战争并与美苏合作。其领导与演说作用需连同帝国政策、资源依赖和盟军整体贡献一起理解。","wars":["ww1","ww2"]},{"name":"斯大林","life":"1878—1953","role":"苏联领导人","bio":"参与德苏协定、苏联战争动员及盟国外交，苏军在巨大牺牲中击败德国的重要力量。战前清洗、初期判断失误、镇压与对他国主权的侵害也属于其责任，不能用胜利替代全面评价。","wars":["ww2"]},{"name":"蒋介石","life":"1887—1975","role":"中国战时主要政治军事领导人","bio":"领导国民政府的长期抗战，参与正面战场指挥及开罗等同盟外交。抗战贡献与军事失利、统治问题及国共摩擦须一并考察，中国军民和其他抗日力量的作用不能归于个人。","wars":["ww2"]},{"name":"毛泽东","life":"1893—1976","role":"中国共产党领导人","bio":"推动抗日民族统一战线与敌后抗战战略，1938年《论持久战》分析长期抵抗的条件与阶段。其战争论述应与根据地、群众动员和实际战局相联系，不能理解为预知每一场战役的详细结果。","wars":["ww2"]},{"name":"彭德怀","life":"1898—1974","role":"中国共产党军事领导人","bio":"抗战期间参与领导八路军作战，组织百团大战等敌后行动。其经历有助理解铁路破袭、根据地生存与日军报复性进攻之间的关系，并应区别战果、损失和长期承受能力。","wars":["ww2"]},{"name":"杜鲁门","life":"1884—1972","role":"美国总统","bio":"1945年继任总统，参与波茨坦会议、对日战争终结与战后政策。其任内原子弹用于日本城市，决策背景、其他选择和对平民后果的争议，应以资料和不同研究审慎比较。","wars":["ww2"]},{"name":"裕仁","life":"1901—1989","role":"日本天皇","bio":"作为日本帝国国家体制核心，与军政决策的关系是战争责任研究的重要问题。1945年参与接受投降的决策并广播宣布，不能以最后终战介入遮蔽更长战争期间的责任讨论。","wars":["ww2"]},{"name":"艾森豪威尔","life":"1890—1969","role":"盟军统帅","bio":"指挥北非等联合行动，担任西北欧盟军最高统帅并组织诺曼底登陆与后续推进。其关键工作包括多国协调、资源分配和政治军事关系，而非独自决定每一场战斗。","wars":["ww2"]},{"name":"朱可夫","life":"1896—1974","role":"苏联将领","bio":"在莫斯科防御、苏军战略反攻与柏林作战等方面发挥重要作用。与其他统帅、部队和工业动员共同构成苏军胜利条件，人物声望不能替代对具体战役责任与代价的讨论。","wars":["ww2"]},{"name":"尼米兹","life":"1885—1966","role":"美国海军将领","bio":"统筹太平洋重要海军行动，中途岛及中太平洋推进是核心关联。其指挥依赖情报、舰队人员、航母航空兵与巨大后勤生产体系，胜利不应被简化为单一灵感。","wars":["ww2"]},{"name":"山本五十六","life":"1884—1943","role":"日本海军将领","bio":"参与策划珍珠港突袭并统率联合舰队。突袭的战术成果没有消除日本长期资源劣势，中途岛等行动又造成严重损失；理解其顾虑不等于把侵略决策包装成无奈。","wars":["ww2"]},{"name":"隆美尔","life":"1891—1944","role":"德国将领","bio":"以北非机动作战著名，后参与西欧防御。战果与失利都受补给、海空力量和轴心资源限制；个人军事声誉不能把所属政权的侵略性质和占领责任从叙述中抽去。","wars":["ww2"]},{"name":"蒙哥马利","life":"1887—1976","role":"英国将领","bio":"指挥阿拉曼等行动，参与诺曼底及西欧战役，也与市场花园受挫相关。重视准备和兵力集中是其特点，仍需放在盟国资源与多国指挥关系中评价。","wars":["ww2"]},{"name":"麦克阿瑟","life":"1880—1964","role":"美国将领","bio":"参与菲律宾防御、撤至澳大利亚后组织西南太平洋推进，1945年主持接受日本投降并领导占领。个人承诺和形象与战略选择交织，菲律宾居民和部队承受的代价同样重要。","wars":["ww2"]},{"name":"戴高乐","life":"1890—1970","role":"自由法国领导人","bio":"1940年从伦敦号召继续抵抗，组织自由法国，争取法国参与解放与战后安排的地位。其行动显示政府停战后国家抵抗仍可延续，也涉及法国不同政治力量间的竞争。","wars":["ww2"]}],"note":"逐月叙事为史实基础上的原创整理；国家处境是编辑解读，不是虚构当事人自述。主战期每月连续，前史与余波选编；并非逐日全史。无虚构对白、现场感官细节或人物内心独白。"};
